CREATE OR REPLACE FUNCTION splitjson._qualified_name(p_table regclass) RETURNS text
LANGUAGE sql STABLE STRICT SET search_path=pg_catalog, pg_temp
RETURN (SELECT format('%I.%I',n.nspname,c.relname) FROM pg_class c
        JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid=p_table);

CREATE OR REPLACE FUNCTION splitjson._view_definition(p_table regclass) RETURNS text
LANGUAGE sql STABLE STRICT SET search_path=pg_catalog, pg_temp
RETURN pg_get_viewdef(p_table,true);

CREATE OR REPLACE FUNCTION splitjson._secure_relation(p_table regclass) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE grantee_name text;
BEGIN
    FOR grantee_name IN SELECT CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(r.rolname) END
        FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a
        LEFT JOIN pg_roles r ON r.oid=a.grantee WHERE c.oid=p_table AND a.grantee<>c.relowner
    LOOP EXECUTE format('REVOKE ALL ON %s FROM %s CASCADE',p_table,grantee_name); END LOOP;
END $$;

CREATE OR REPLACE FUNCTION splitjson._storage_definition(p_table regclass) RETURNS jsonb
LANGUAGE sql STABLE STRICT SET search_path=pg_catalog, pg_temp
RETURN (SELECT jsonb_agg(jsonb_build_object('name',attname,'type',format_type(atttypid,atttypmod),
                'collation',attcollation::regcollation::text,'generated',attgenerated,'identity',attidentity)
                ORDER BY attnum)
        FROM pg_attribute WHERE attrelid=p_table AND attnum>0 AND NOT attisdropped);

-- A path segment naming an array element must be an integer when it is
-- traversed below an existing object path.  jsonb #- has a subtle edge case:
-- applying a non-integer segment to an array at the root is a no-op, while the
-- same segment after an object key raises 22P02.  Fast delete paths start at a
-- hot subtree, so inspect that subtree before using the short update.  This
-- keeps the short path cold-free while preserving native JSONB errors.
CREATE OR REPLACE FUNCTION splitjson._array_path_requires_fallback(p_value jsonb,p_path text[])
RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog, pg_temp
AS $$
DECLARE cursor jsonb := p_value; i integer; segment text;
BEGIN
    FOR i IN 1..cardinality(p_path) LOOP
        segment := p_path[i];
        IF jsonb_typeof(cursor)='array' AND segment !~ '^[[:space:]]*[+-]?[0-9]+$' THEN
            RETURN true;
        END IF;
        cursor := cursor #> ARRAY[segment];
        IF cursor IS NULL THEN RETURN false; END IF;
    END LOOP;
    RETURN false;
END $$;

CREATE OR REPLACE FUNCTION splitjson._validate_mapping(p_meta splitjson._tables) RETURNS void
LANGUAGE plpgsql STABLE SET search_path=pg_catalog, pg_temp
AS $$
DECLARE v oid; s oid; installer oid; hot_count integer; expected_count integer;
BEGIN
    v := to_regclass(p_meta.view_name); s := to_regclass(p_meta.storage_name);
    SELECT extowner INTO installer FROM pg_extension WHERE extname='pg_splitjson';
    IF v IS NULL OR s IS NULL OR
       NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=v AND relkind='v' AND relowner=installer
                  AND reloptions @> ARRAY['security_barrier=true'] AND
                  NOT coalesce(reloptions @> ARRAY['security_invoker=true'],false)) OR
       NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=s AND relkind='r' AND relowner=installer
                  AND relpersistence='p' AND NOT relrowsecurity AND NOT relforcerowsecurity
                  AND relnamespace=to_regnamespace('splitjson_storage')) THEN
        RAISE EXCEPTION 'invalid managed relation, ownership or unsupported RLS/storage layout: %',p_meta.view_name
            USING ERRCODE='55000';
    END IF;
    PERFORM splitjson.validate_paths(p_meta.paths);
    hot_count := jsonb_array_length(p_meta.paths);
    expected_count := 2+hot_count+(SELECT count(*) FROM jsonb_object_keys(p_meta.business_columns));
    IF hot_count=0 OR jsonb_array_length(p_meta.storage_definition) IS DISTINCT FROM expected_count OR
       splitjson._storage_definition(s) IS DISTINCT FROM p_meta.storage_definition OR
       splitjson._view_definition(v) IS DISTINCT FROM p_meta.view_definition OR
       NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=s AND attnum=1 AND attname='id'
                  AND atttypid='int8'::regtype AND attnotnull) OR
       NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=s AND attnum=2 AND attname='cold'
                  AND atttypid='splitjson.cold'::regtype AND attnotnull AND attstorage='e') OR
       NOT EXISTS(SELECT 1 FROM pg_index WHERE indrelid=s AND indisprimary AND indisvalid
                  AND indnkeyatts=1 AND indkey[0]=1) OR
       NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=v AND tgname='pg_splitjson_write'
                  AND tgfoid='splitjson._view_write()'::regprocedure AND tgenabled='O' AND tgtype=93) OR
       EXISTS(SELECT 1 FROM generate_series(1,hot_count) i WHERE
                  NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=s AND attname='hot_'||i
                             AND atttypid='jsonb'::regtype AND NOT attisdropped)) THEN
        RAISE EXCEPTION 'managed mapping has drifted: %; restore its layout before use',p_meta.view_name
            USING ERRCODE='55000';
    END IF;
END $$;

CREATE OR REPLACE FUNCTION splitjson.storage_relation(p_table regclass) RETURNS regclass
LANGUAGE plpgsql STABLE SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    RETURN meta.storage_name::regclass;
END $$;

CREATE OR REPLACE FUNCTION splitjson.check_table(p_table regclass,p_check_data boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; rows_checked bigint := 0; invalid_indexes bigint;
BEGIN
    IF p_check_data IS NULL THEN RAISE EXCEPTION 'check_data must not be NULL' USING ERRCODE='22023'; END IF;
    meta := splitjson._lookup(p_table,'SELECT');
    IF p_check_data THEN
        EXECUTE format('SELECT count(splitjson.restore(cold,%s,$1)) FROM %s',
                       splitjson._hot_array(meta.paths),meta.storage_name) INTO rows_checked USING meta.paths;
    END IF;
    SELECT count(*) INTO invalid_indexes FROM pg_index
        WHERE indrelid=meta.storage_name::regclass AND (NOT indisvalid OR NOT indisready);
    RETURN jsonb_build_object('view',meta.view_name,'storage',meta.storage_name,
               'layout_ok',true,'rows_checked',rows_checked,'invalid_indexes',invalid_indexes);
END $$;

CREATE OR REPLACE FUNCTION splitjson.check_all(p_check_data boolean DEFAULT false) RETURNS SETOF jsonb
LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE relation text;
BEGIN
    FOR relation IN SELECT view_name FROM splitjson._tables ORDER BY view_name LOOP
        RETURN NEXT splitjson.check_table(relation::regclass,p_check_data);
    END LOOP;
END $$;

CREATE OR REPLACE FUNCTION splitjson.table_stats(p_table regclass) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; stats jsonb;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    SELECT to_jsonb(s) || jsonb_build_object('view',meta.view_name,
        'total_bytes',pg_total_relation_size(s.relid),'heap_bytes',pg_relation_size(s.relid),
        'indexes_bytes',pg_indexes_size(s.relid)) INTO stats
        FROM pg_stat_user_tables s WHERE relid=meta.storage_name::regclass;
    RETURN stats;
END $$;

CREATE OR REPLACE FUNCTION splitjson.rename_table(p_table regclass,p_name text) RETURNS regclass
LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; parts text[]; oldparts text[]; target text;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    parts := parse_ident(p_name,true); oldparts := parse_ident(meta.view_name,true);
    IF cardinality(parts)<>2 OR parts[1]<>oldparts[1] OR octet_length(parts[2])>63 THEN
        RAISE EXCEPTION 'use a schema-qualified name in the same business schema' USING ERRCODE='22023';
    END IF;
    target := format('%I.%I',parts[1],parts[2]);
    IF to_regclass(target) IS NOT NULL THEN RAISE EXCEPTION 'target already exists' USING ERRCODE='42P07'; END IF;
    UPDATE splitjson._tables SET view_name=target WHERE view_name=meta.view_name;
    EXECUTE format('ALTER VIEW %s RENAME TO %I',meta.view_name,parts[2]);
    RETURN target::regclass;
END $$;

CREATE OR REPLACE FUNCTION splitjson.set_business_not_null(p_table regclass,p_column text,p_enabled boolean DEFAULT true)
RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; slot integer;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    -- Use the same C ordering as create_table, not jsonb key-length ordering.
    SELECT n INTO slot FROM (SELECT key,row_number() OVER (ORDER BY key COLLATE "C")::integer n
                            FROM jsonb_each_text(meta.business_columns)) c WHERE key=p_column;
    IF slot IS NULL OR p_enabled IS NULL THEN RAISE EXCEPTION 'unknown business column or NULL flag' USING ERRCODE='22023'; END IF;
    EXECUTE format('ALTER TABLE %s ALTER COLUMN extra_%s %s NOT NULL',
                   meta.storage_name,slot,CASE WHEN p_enabled THEN 'SET' ELSE 'DROP' END);
END $$;

CREATE OR REPLACE FUNCTION splitjson.set_business_default(p_table regclass,p_column text,p_value jsonb)
RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; slot integer; declaration text; literal text;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    SELECT n,value INTO slot,declaration FROM (SELECT key,value,
        row_number() OVER (ORDER BY key COLLATE "C")::integer n FROM jsonb_each_text(meta.business_columns)) c
        WHERE key=p_column;
    IF slot IS NULL THEN RAISE EXCEPTION 'unknown business column' USING ERRCODE='22023'; END IF;
    IF p_value IS NULL THEN
        EXECUTE format('ALTER TABLE %s ALTER COLUMN extra_%s DROP DEFAULT',meta.storage_name,slot);
        EXECUTE format('ALTER VIEW %s ALTER COLUMN %I DROP DEFAULT',meta.view_name,p_column);
    ELSE
        EXECUTE format('SELECT ((jsonb_populate_record(NULL::%s,$1)).%I)::text',meta.view_name,p_column)
            INTO literal USING jsonb_build_object(p_column,p_value);
        EXECUTE format('ALTER TABLE %s ALTER COLUMN extra_%s SET DEFAULT %L::%s',meta.storage_name,slot,literal,declaration);
        EXECUTE format('ALTER VIEW %s ALTER COLUMN %I SET DEFAULT %L::%s',meta.view_name,p_column,literal,declaration);
    END IF;
END $$;

CREATE OR REPLACE FUNCTION splitjson.add_field_check(p_table regclass,p_name text,p_path jsonb,
                                                    p_type text,p_required boolean DEFAULT false)
RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; slot integer; condition text; parts text[];
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    PERFORM splitjson.validate_paths(jsonb_build_array(p_path));
    parts := parse_ident(p_name,true);
    IF p_type IS NULL OR p_required IS NULL OR cardinality(parts)<>1 OR octet_length(parts[1])>63 OR
       p_type NOT IN ('object','array','string','number','boolean','null') THEN
        RAISE EXCEPTION 'invalid check name or JSON type' USING ERRCODE='22023';
    END IF;
    SELECT ord::integer INTO slot FROM jsonb_array_elements(meta.paths) WITH ORDINALITY p(path,ord) WHERE path=p_path;
    IF slot IS NULL THEN RAISE EXCEPTION 'check path must be a registered hot slot' USING ERRCODE='22023'; END IF;
    condition := format('jsonb_typeof(hot_%s)=%L',slot,p_type);
    IF p_required THEN condition := format('hot_%s IS NOT NULL AND (%s)',slot,condition); END IF;
    EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I CHECK (%s)',meta.storage_name,parts[1],condition);
END $$;

CREATE OR REPLACE FUNCTION splitjson.index_ddl(p_table regclass,p_name text,p_path jsonb,
                                             p_kind text DEFAULT 'jsonb',p_unique boolean DEFAULT false)
RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; slot integer; parts text[]; expression text;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    PERFORM splitjson.validate_paths(jsonb_build_array(p_path));
    parts := parse_ident(p_name,true);
    IF p_kind IS NULL OR p_unique IS NULL OR cardinality(parts)<>1 OR octet_length(parts[1])>63 OR
       p_kind NOT IN ('jsonb','text') THEN RAISE EXCEPTION 'invalid index declaration' USING ERRCODE='22023'; END IF;
    SELECT ord::integer INTO slot FROM jsonb_array_elements(meta.paths) WITH ORDINALITY p(path,ord) WHERE path=p_path;
    IF slot IS NULL THEN RAISE EXCEPTION 'path must be a registered hot slot' USING ERRCODE='22023'; END IF;
    expression := format('hot_%s',slot);
    IF p_kind='text' THEN expression := format('(%s #>> %L::text[])',expression,'{}'); END IF;
    RETURN format('CREATE %sINDEX CONCURRENTLY %I ON %s USING btree (%s);',
                  CASE WHEN p_unique THEN 'UNIQUE ' ELSE '' END,parts[1],meta.storage_name,expression);
END $$;

CREATE OR REPLACE FUNCTION splitjson._ddl_end_guard() RETURNS event_trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE;
BEGIN
    IF to_regclass('splitjson._tables') IS NULL THEN RETURN; END IF;
    FOR meta IN SELECT * FROM splitjson._tables LOOP PERFORM splitjson._validate_mapping(meta); END LOOP;
END $$;

CREATE OR REPLACE FUNCTION splitjson._sql_drop_guard() RETURNS event_trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
BEGIN
    IF to_regclass('splitjson._tables') IS NULL THEN RETURN; END IF;
    IF EXISTS(SELECT 1 FROM pg_event_trigger_dropped_objects() d JOIN splitjson._tables m
        ON format('%I.%I',d.schema_name,d.object_name) IN (m.view_name,m.storage_name)
        WHERE d.object_type IN ('table','view')) THEN
        RAISE EXCEPTION 'use splitjson.drop_table to remove managed relations' USING ERRCODE='55000';
    END IF;
END $$;

CREATE OR REPLACE FUNCTION splitjson._ddl_start_guard() RETURNS event_trigger
AS 'MODULE_PATHNAME','pg_splitjson_ddl_start_guard' LANGUAGE C SECURITY DEFINER SET search_path=pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION splitjson._caller() RETURNS name
LANGUAGE sql STABLE SET search_path = pg_catalog, pg_temp
RETURN CASE WHEN current_setting('role') = 'none' THEN session_user::name
            ELSE current_setting('role')::name END;

CREATE OR REPLACE FUNCTION splitjson._hot_array(p_paths jsonb) RETURNS text
LANGUAGE sql IMMUTABLE STRICT SET search_path = pg_catalog, pg_temp
RETURN (SELECT 'ARRAY[' || string_agg(format('hot_%s', n), ',') || ']::jsonb[]'
        FROM generate_series(1, jsonb_array_length(p_paths)) AS n);

CREATE OR REPLACE FUNCTION splitjson._assignments(p_paths jsonb) RETURNS text
LANGUAGE sql IMMUTABLE STRICT SET search_path = pg_catalog, pg_temp
RETURN (SELECT string_agg(format('hot_%s=($2)[%s]', n, n), ',')
        FROM generate_series(1, jsonb_array_length(p_paths)) AS n);

CREATE OR REPLACE FUNCTION splitjson._lookup(p_table regclass, p_privilege text)
RETURNS splitjson._tables LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE;
BEGIN
    IF p_table IS NULL THEN RAISE EXCEPTION 'table must not be NULL' USING ERRCODE='22023'; END IF;
    SELECT * INTO meta FROM splitjson._tables WHERE view_name=splitjson._qualified_name(p_table);
    IF NOT FOUND THEN
        RAISE EXCEPTION 'relation is not a pg_splitjson managed view' USING ERRCODE='22023';
    END IF;
    IF NOT has_column_privilege(splitjson._caller(),p_table,'doc',p_privilege) OR
       (p_privilege='SELECT' AND NOT has_column_privilege(splitjson._caller(),p_table,'id','SELECT')) THEN
        RAISE EXCEPTION 'permission denied for JSON %',lower(p_privilege) USING ERRCODE='42501';
    END IF;
    PERFORM splitjson._validate_mapping(meta);
    IF NOT has_schema_privilege(splitjson._caller(), (SELECT relnamespace FROM pg_class WHERE oid=p_table), 'USAGE') THEN
        RAISE EXCEPTION 'permission denied for business schema' USING ERRCODE='42501';
    END IF;
    RETURN meta;
END $$;
REVOKE ALL ON FUNCTION splitjson._lookup(regclass,text) FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson._slot(p_paths jsonb,p_path text[]) RETURNS integer
LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog, pg_temp
RETURN (SELECT ord::integer FROM jsonb_array_elements(p_paths) WITH ORDINALITY AS p(path,ord)
        WHERE path=to_jsonb(p_path));

CREATE OR REPLACE FUNCTION splitjson._save(p_storage text, p_id bigint, p_doc jsonb, p_paths jsonb)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
AS $$
DECLARE affected bigint;
BEGIN
    IF p_doc IS NULL THEN
        RAISE EXCEPTION 'doc must not be SQL NULL; JSON null is allowed' USING ERRCODE = '23502';
    END IF;
    EXECUTE format('UPDATE %s SET cold=$1,%s WHERE id=$3',
                   p_storage, splitjson._assignments(p_paths))
        USING splitjson.pack(p_doc, p_paths), splitjson.slots(p_doc, p_paths), p_id;
    GET DIAGNOSTICS affected = ROW_COUNT;
    RETURN affected = 1;
END $$;
REVOKE ALL ON FUNCTION splitjson._save(text,bigint,jsonb,jsonb) FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson._view_write() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    meta splitjson._tables%ROWTYPE;
    hot_columns text;
    hot_params text;
    n integer;
    current_row jsonb;
    affected bigint;
    column_name text;
    column_type text;
    extra_columns text := '';
    extra_values text := '';
    extra_assignments text := '';
BEGIN
    SELECT * INTO STRICT meta FROM splitjson._tables WHERE view_name=splitjson._qualified_name(TG_RELID);
    PERFORM splitjson._validate_mapping(meta);
    n := 0;
    FOR column_name,column_type IN SELECT key,value FROM jsonb_each_text(meta.business_columns) ORDER BY key COLLATE "C" LOOP
        n := n+1;
        extra_columns := extra_columns || format(',extra_%s',n);
        extra_values := extra_values || format(',($4::%s).%I',meta.view_name,column_name);
        extra_assignments := extra_assignments || format(',extra_%s=($5::%s).%I',n,meta.view_name,column_name);
    END LOOP;
    IF TG_OP <> 'INSERT' THEN
        EXECUTE format('SELECT to_jsonb(ROW(id,splitjson.restore(cold,%s)%s)::%s) FROM %s WHERE id=$1 FOR UPDATE',
                       splitjson._hot_array(meta.paths),extra_columns,meta.view_name,meta.storage_name)
            INTO current_row USING OLD.id;
        GET DIAGNOSTICS affected = ROW_COUNT;
        IF affected = 0 THEN RETURN NULL; END IF;
        -- An INSTEAD OF trigger cannot re-evaluate the original UPDATE/DELETE
        -- expression like the heap executor's EvalPlanQual. Require a retry.
        IF current_row IS DISTINCT FROM to_jsonb(OLD) THEN
            RAISE EXCEPTION 'concurrent row modification; retry the statement or transaction'
                USING ERRCODE = '40001';
        END IF;
    END IF;
    IF TG_OP = 'DELETE' THEN
        EXECUTE format('DELETE FROM %s WHERE id=$1', meta.storage_name) USING OLD.id;
        RETURN OLD;
    END IF;
    IF NEW.id IS NULL OR NEW.doc IS NULL THEN
        RAISE EXCEPTION 'id and doc must not be SQL NULL' USING ERRCODE = '23502';
    END IF;
    IF TG_OP = 'INSERT' THEN
        FOR n IN 1..jsonb_array_length(meta.paths) LOOP
            hot_columns := concat_ws(',', hot_columns, format('hot_%s', n));
            hot_params := concat_ws(',', hot_params, format('($3)[%s]', n));
        END LOOP;
        EXECUTE format('INSERT INTO %s (id,cold,%s%s) VALUES ($1,$2,%s%s)',
                       meta.storage_name,hot_columns,extra_columns,hot_params,extra_values)
            USING NEW.id,splitjson.pack(NEW.doc,meta.paths),splitjson.slots(NEW.doc,meta.paths),NEW;
    ELSE
        IF NEW.doc IS NOT DISTINCT FROM OLD.doc THEN
            EXECUTE format('UPDATE %s SET id=$4%s WHERE id=$3',meta.storage_name,extra_assignments)
                USING NULL::splitjson.cold,NULL::jsonb[],OLD.id,NEW.id,NEW;
        ELSE
            EXECUTE format('UPDATE %s SET id=$4,cold=$1,%s%s WHERE id=$3',
                           meta.storage_name,splitjson._assignments(meta.paths),extra_assignments)
                USING splitjson.pack(NEW.doc,meta.paths),splitjson.slots(NEW.doc,meta.paths),OLD.id,NEW.id,NEW;
        END IF;
    END IF;
    RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION splitjson._view_write() FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson.create_table(p_name text, p_paths jsonb, p_columns jsonb DEFAULT '{}') RETURNS regclass
LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    parts text[];
    logical_name text;
    storage_name text;
    columns text := '';
    n integer;
    column_name text;
    declared_type jsonb;
    normalized_type text;
    normalized_columns jsonb := '{}';
    extra_select text := '';
BEGIN
    IF p_name IS NULL OR p_paths IS NULL OR p_columns IS NULL THEN
        RAISE EXCEPTION 'table name and paths must not be NULL' USING ERRCODE = '22023';
    END IF;
    PERFORM splitjson.validate_paths(p_paths);
    IF jsonb_array_length(p_paths) = 0 THEN
        RAISE EXCEPTION 'declare at least one hot path' USING ERRCODE = '22023';
    END IF;
    parts := parse_ident(p_name, true);
    IF cardinality(parts) <> 2 THEN
        RAISE EXCEPTION 'use a schema-qualified name, for example public.docs' USING ERRCODE = '22023';
    END IF;
    -- Avoid PostgreSQL identifier truncation creating ambiguous metadata names.
    IF octet_length(parts[1]) > 63 OR octet_length(parts[2]) > 63 THEN
        RAISE EXCEPTION 'schema and relation names must fit PostgreSQL identifiers' USING ERRCODE = '22023';
    END IF;
    logical_name := format('%I.%I', parts[1], parts[2]);
    IF jsonb_typeof(p_columns)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(p_columns))>64 THEN
        RAISE EXCEPTION 'business columns must be an object with at most 64 entries' USING ERRCODE='22023';
    END IF;
    n := 0;
    FOR column_name,declared_type IN SELECT key,value FROM jsonb_each(p_columns) ORDER BY key COLLATE "C" LOOP
        IF column_name IN ('id','doc') OR column_name='' OR octet_length(column_name)>63 OR jsonb_typeof(declared_type)<>'string' THEN
            RAISE EXCEPTION 'invalid business column name or type declaration' USING ERRCODE='22023';
        END IF;
        normalized_type := splitjson.column_type(declared_type #>> '{}');
        normalized_columns := normalized_columns || jsonb_build_object(column_name,normalized_type);
        n := n+1;
        columns := columns || format(',extra_%s %s',n,normalized_type);
        extra_select := extra_select || format(',extra_%s AS %I',n,column_name);
    END LOOP;
    storage_name := format('splitjson_storage.s_%s', nextval('splitjson._table_id_seq'));
    FOR n IN 1..jsonb_array_length(p_paths) LOOP
        columns := columns || format(',hot_%s jsonb', n);
    END LOOP;
    EXECUTE format('CREATE TABLE %s (id bigint PRIMARY KEY,cold splitjson.cold NOT NULL%s) WITH (fillfactor=70)',
                   storage_name, columns);
    EXECUTE format('ALTER TABLE %s ALTER COLUMN cold SET STORAGE EXTERNAL', storage_name);
    EXECUTE format('CREATE VIEW %s WITH (security_barrier=true) AS '
                   'SELECT id,splitjson.restore(cold,%s,%L::jsonb) AS doc%s FROM %s',
                   logical_name,splitjson._hot_array(p_paths),p_paths::text,extra_select,storage_name);
    PERFORM splitjson._secure_relation(storage_name::regclass);
    INSERT INTO splitjson._tables(view_name,storage_name,paths,business_columns,view_definition,storage_definition)
        VALUES(logical_name,storage_name,p_paths,normalized_columns,splitjson._view_definition(logical_name::regclass),
               splitjson._storage_definition(storage_name::regclass));
    EXECUTE format('CREATE TRIGGER pg_splitjson_write INSTEAD OF INSERT OR UPDATE OR DELETE ON %s '
                   'FOR EACH ROW EXECUTE FUNCTION splitjson._view_write()', logical_name);
    RETURN logical_name::regclass;
END $$;

-- Fast path: the SELECT and UPDATE below mention only id and hot_N, never cold.
CREATE OR REPLACE FUNCTION splitjson.set_field(p_table regclass,p_id bigint,p_path text[],p_value jsonb,
                                      p_create_missing boolean DEFAULT true)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
BEGIN
    IF p_table IS NULL OR p_id IS NULL OR p_path IS NULL OR p_value IS NULL OR p_create_missing IS NULL THEN
        RAISE EXCEPTION 'arguments must not be NULL; use JSON null' USING ERRCODE='22023';
    END IF;
    PERFORM splitjson.assert_object_path('{}',p_path);
    p_path := ARRAY(SELECT unnest(p_path));
    RETURN splitjson.set_fields(p_table,p_id,jsonb_build_array(jsonb_build_object('path',to_jsonb(p_path),'value',p_value)),p_create_missing);
END $$;

CREATE OR REPLACE FUNCTION splitjson.delete_field(p_table regclass,p_id bigint,p_path text[])
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; hot jsonb[]; slot integer; relative text[]; doc jsonb; affected bigint;
BEGIN
    IF p_id IS NULL OR p_path IS NULL THEN RAISE EXCEPTION 'arguments must not be NULL' USING ERRCODE='22023'; END IF;
    PERFORM splitjson.assert_object_path('{}',p_path);
    p_path := ARRAY(SELECT unnest(p_path));
    meta := splitjson._lookup(p_table,'UPDATE');
    EXECUTE format('SELECT %s FROM %s WHERE id=$1 FOR UPDATE',splitjson._hot_array(meta.paths),meta.storage_name)
        INTO hot USING p_id;
    GET DIAGNOSTICS affected=ROW_COUNT;
    IF affected=0 THEN RETURN false; END IF;
    slot := splitjson._hot_route(meta.paths,p_path,hot);
    IF slot IS NOT NULL AND jsonb_array_length(meta.paths->(slot-1))<cardinality(p_path)
       AND NOT splitjson._array_path_requires_fallback(
                    hot[slot],p_path[jsonb_array_length(meta.paths->(slot-1))+1:cardinality(p_path)]) THEN
        relative := p_path[jsonb_array_length(meta.paths->(slot-1))+1:cardinality(p_path)];
        EXECUTE format('UPDATE %s SET hot_%s=$1 WHERE id=$2',meta.storage_name,slot) USING hot[slot] #- relative,p_id;
        RETURN true;
    END IF;
    EXECUTE format('SELECT splitjson.restore(cold,%s) FROM %s WHERE id=$1',splitjson._hot_array(meta.paths),meta.storage_name)
        INTO doc USING p_id;
    RETURN splitjson._save(meta.storage_name,p_id,doc #- p_path,meta.paths);
END $$;

CREATE OR REPLACE FUNCTION splitjson.drop_table(p_table regclass) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; owner_oid oid; caller_oid oid;
BEGIN
    IF p_table IS NULL THEN RAISE EXCEPTION 'table must not be NULL' USING ERRCODE = '22023'; END IF;
    SELECT * INTO meta FROM splitjson._tables WHERE view_name=splitjson._qualified_name(p_table);
    IF NOT FOUND THEN RAISE EXCEPTION 'relation is not a pg_splitjson managed view' USING ERRCODE = '22023'; END IF;
    SELECT relowner INTO owner_oid FROM pg_class WHERE oid = p_table;
    SELECT oid INTO caller_oid FROM pg_roles WHERE rolname = splitjson._caller();
    IF NOT pg_has_role(caller_oid, owner_oid, 'USAGE') THEN
        RAISE EXCEPTION 'must own the managed view to drop it' USING ERRCODE = '42501';
    END IF;
    PERFORM splitjson._validate_mapping(meta);
    -- Remove the registration in this transaction before protected DDL.
    -- Any dependency error rolls this deletion back with the DDL.
    DELETE FROM splitjson._tables WHERE view_name=meta.view_name;
    EXECUTE format('DROP VIEW %s', meta.view_name);
    EXECUTE format('DROP TABLE %s', meta.storage_name);
    DELETE FROM splitjson._tables WHERE view_name = meta.view_name;
END $$;

CREATE OR REPLACE FUNCTION splitjson.set_fields(p_table regclass,p_id bigint,p_updates jsonb,
                                     p_create_missing boolean DEFAULT true)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE
    meta splitjson._tables%ROWTYPE;
    operation jsonb;
    path text[];
    relative text[];
    hot jsonb[];
    touched integer[] := '{}';
    slot integer;
    depth integer;
    all_hot boolean := true;
    affected bigint;
    assignments text;
    doc jsonb;
BEGIN
    IF p_id IS NULL OR p_updates IS NULL OR p_create_missing IS NULL OR jsonb_typeof(p_updates)<>'array' THEN
        RAISE EXCEPTION 'updates must be an array; arguments must not be NULL' USING ERRCODE='22023';
    END IF;
    IF jsonb_array_length(p_updates) NOT BETWEEN 1 AND 64 THEN
        RAISE EXCEPTION 'a batch must contain between 1 and 64 operations' USING ERRCODE='22023';
    END IF;
    FOR operation IN SELECT value FROM jsonb_array_elements(p_updates) LOOP
        IF jsonb_typeof(operation)<>'object' THEN
            RAISE EXCEPTION 'each operation must contain exactly path and value' USING ERRCODE='22023';
        END IF;
        IF (SELECT count(*) FROM jsonb_object_keys(operation))<>2 OR NOT operation ? 'path' OR NOT operation ? 'value' THEN
            RAISE EXCEPTION 'each operation must contain exactly path and value' USING ERRCODE='22023';
        END IF;
        IF jsonb_typeof(operation->'path')<>'array' OR
           EXISTS(SELECT 1 FROM jsonb_array_elements(operation->'path') e WHERE jsonb_typeof(e)<>'string') THEN
            RAISE EXCEPTION 'operation path must be an array of string segments' USING ERRCODE='22023';
        END IF;
        path := ARRAY(SELECT jsonb_array_elements_text(operation->'path'));
        PERFORM splitjson.assert_object_path('{}',path);
    END LOOP;
    meta := splitjson._lookup(p_table,'UPDATE');
    EXECUTE format('SELECT %s FROM %s WHERE id=$1 FOR UPDATE',splitjson._hot_array(meta.paths),meta.storage_name)
        INTO hot USING p_id;
    GET DIAGNOSTICS affected=ROW_COUNT;
    IF affected=0 THEN RETURN false; END IF;
    FOR operation IN SELECT value FROM jsonb_array_elements(p_updates) LOOP
        path := ARRAY(SELECT jsonb_array_elements_text(operation->'path'));
        slot := splitjson._hot_route(meta.paths,path,hot);
        IF slot IS NULL THEN all_hot := false; EXIT; END IF;
        depth := jsonb_array_length(meta.paths->(slot-1));
        relative := path[depth+1:cardinality(path)];
        IF cardinality(relative)=0 THEN hot[slot] := operation->'value';
        ELSE hot[slot] := jsonb_set(hot[slot],relative,operation->'value',p_create_missing); END IF;
        touched := array_append(touched,slot);
    END LOOP;
    IF all_hot THEN
        SELECT string_agg(format('hot_%s=($1)[%s]',n,n),',' ORDER BY n) INTO assignments
            FROM (SELECT DISTINCT unnest(touched) AS n) t;
        EXECUTE format('UPDATE %s SET %s WHERE id=$2',meta.storage_name,assignments) USING hot,p_id;
        RETURN true;
    END IF;
    EXECUTE format('SELECT splitjson.restore(cold,%s) FROM %s WHERE id=$1',splitjson._hot_array(meta.paths),meta.storage_name)
        INTO doc USING p_id;
    FOR operation IN SELECT value FROM jsonb_array_elements(p_updates) LOOP
        path := ARRAY(SELECT jsonb_array_elements_text(operation->'path'));
        doc := jsonb_set(doc,path,operation->'value',p_create_missing);
    END LOOP;
    RETURN splitjson._save(meta.storage_name,p_id,doc,meta.paths);
END $$;

CREATE OR REPLACE FUNCTION splitjson.increment_field(p_table regclass,p_id bigint,p_path text[],p_delta numeric DEFAULT 1)
RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; hot jsonb[]; slot integer; relative text[]; value jsonb; doc jsonb; result numeric; affected bigint;
BEGIN
    IF p_id IS NULL OR p_path IS NULL OR p_delta IS NULL OR p_delta::text IN ('NaN','Infinity','-Infinity') THEN
        RAISE EXCEPTION 'arguments must not be NULL and delta must be finite' USING ERRCODE='22023';
    END IF;
    PERFORM splitjson.assert_object_path('{}',p_path);
    p_path := ARRAY(SELECT unnest(p_path));
    meta := splitjson._lookup(p_table,'UPDATE');
    EXECUTE format('SELECT %s FROM %s WHERE id=$1 FOR UPDATE',splitjson._hot_array(meta.paths),meta.storage_name)
        INTO hot USING p_id;
    GET DIAGNOSTICS affected=ROW_COUNT;
    IF affected=0 THEN RETURN NULL; END IF;
    slot := splitjson._hot_route(meta.paths,p_path,hot);
    IF slot IS NOT NULL THEN
        relative := p_path[jsonb_array_length(meta.paths->(slot-1))+1:cardinality(p_path)];
        value := hot[slot] #> relative;
    ELSE
        EXECUTE format('SELECT splitjson.restore(cold,%s) FROM %s WHERE id=$1',splitjson._hot_array(meta.paths),meta.storage_name)
            INTO doc USING p_id;
        value := doc #> p_path;
    END IF;
    IF value IS NULL OR jsonb_typeof(value)<>'number' THEN
        RAISE EXCEPTION 'increment target must be an existing JSON number' USING ERRCODE='22023';
    END IF;
    result := value::text::numeric+p_delta;
    IF slot IS NOT NULL THEN
        IF cardinality(relative)=0 THEN value := to_jsonb(result);
        ELSE value := jsonb_set(hot[slot],relative,to_jsonb(result),false); END IF;
        EXECUTE format('UPDATE %s SET hot_%s=$1 WHERE id=$2',meta.storage_name,slot) USING value,p_id;
    ELSE
        PERFORM splitjson._save(meta.storage_name,p_id,jsonb_set(doc,p_path,to_jsonb(result),false),meta.paths);
    END IF;
    RETURN result;
END $$;

CREATE OR REPLACE FUNCTION splitjson.migrate_table(p_source regclass,p_target text,p_paths jsonb,
                                           p_doc_column name DEFAULT 'doc',p_id_column name DEFAULT 'id')
RETURNS regclass LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE
    columns jsonb;
    target regclass;
    names text := '';
    column_name text;
    declaration text;
BEGIN
    IF p_source IS NULL OR p_doc_column IS NULL OR p_id_column IS NULL OR p_doc_column=p_id_column OR
       NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=p_source AND relkind='r') THEN
        RAISE EXCEPTION 'source must be an ordinary table with distinct id/doc columns' USING ERRCODE='22023';
    END IF;
    -- Hold source DDL stable for the complete snapshot copy.
    EXECUTE format('LOCK TABLE %s IN ACCESS SHARE MODE',p_source);
    IF NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=p_source AND attname=p_id_column
                  AND NOT attisdropped AND atttypid='int8'::regtype) OR
       NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=p_source AND attname=p_doc_column
                  AND NOT attisdropped AND atttypid='jsonb'::regtype) THEN
        RAISE EXCEPTION 'source id must be bigint and document must be jsonb' USING ERRCODE='22023';
    END IF;
    SELECT coalesce(jsonb_object_agg(attname,format_type(atttypid,atttypmod)),'{}') INTO columns
        FROM pg_attribute WHERE attrelid=p_source AND attnum>0 AND NOT attisdropped
        AND attname NOT IN (p_id_column,p_doc_column);
    FOR column_name,declaration IN SELECT key,value FROM jsonb_each_text(columns) ORDER BY key COLLATE "C" LOOP
        names := names || format(',%I',column_name);
    END LOOP;
    target := splitjson.create_table(p_target,p_paths,columns);
    EXECUTE format('INSERT INTO %s (id,doc%s) SELECT %I,%I%s FROM %s',
                   target,names,p_id_column,p_doc_column,names,p_source);
    RETURN target;
END $$;

CREATE OR REPLACE FUNCTION splitjson.get_field(p_table regclass,p_id bigint,p_path text[]) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; hot jsonb[]; slot integer; value jsonb; affected bigint;
BEGIN
    IF p_id IS NULL OR p_path IS NULL THEN RAISE EXCEPTION 'arguments must not be NULL' USING ERRCODE='22023'; END IF;
    PERFORM splitjson.assert_object_path('{}',p_path);
    p_path := ARRAY(SELECT unnest(p_path));
    meta := splitjson._lookup(p_table,'SELECT');
    EXECUTE format('SELECT %s FROM %s WHERE id=$1',splitjson._hot_array(meta.paths),meta.storage_name) INTO hot USING p_id;
    GET DIAGNOSTICS affected=ROW_COUNT;
    IF affected=0 THEN RETURN NULL; END IF;
    slot := splitjson._hot_route(meta.paths,p_path,hot);
    IF slot IS NOT NULL THEN
        RETURN hot[slot] #> p_path[jsonb_array_length(meta.paths->(slot-1))+1:cardinality(p_path)];
    END IF;
    EXECUTE format('SELECT splitjson.restore(cold,%s) #> $2 FROM %s WHERE id=$1',splitjson._hot_array(meta.paths),meta.storage_name)
        INTO value USING p_id,p_path;
    RETURN value;
END $$;

CREATE OR REPLACE FUNCTION splitjson._find_query(p_meta splitjson._tables,p_path text[]) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog, pg_temp
AS $$
DECLARE candidates integer[]; condition text; missing text;
BEGIN
    candidates := splitjson._path_candidates(p_meta.paths,p_path);
    IF cardinality(candidates)>0 THEN
        SELECT string_agg(format('hot_%s=$1',n),' OR ') INTO condition FROM unnest(candidates) n;
        -- Native text paths may address shapes not covered by declared typed slots.
        IF EXISTS(SELECT 1 FROM unnest(p_path) key WHERE key ~ '^[[:space:]]*[+-]?[0-9]+$') THEN
            SELECT string_agg(format('hot_%s IS NULL',n),' AND ') INTO missing FROM unnest(candidates) n;
            condition := condition || format(' OR (%s AND splitjson.restore(cold,%s) #> $2=$1)',
                                               missing,splitjson._hot_array(p_meta.paths));
        END IF;
        RETURN format('SELECT id FROM %s WHERE %s',p_meta.storage_name,condition);
    END IF;
    RETURN format('SELECT id FROM %s WHERE splitjson.restore(cold,%s) #> $2=$1',p_meta.storage_name,splitjson._hot_array(p_meta.paths));
END $$;
REVOKE ALL ON FUNCTION splitjson._find_query(splitjson._tables,text[]) FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson.find_ids(p_table regclass,p_path text[],p_value jsonb) RETURNS SETOF bigint
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE;
BEGIN
    IF p_path IS NULL OR p_value IS NULL THEN RAISE EXCEPTION 'arguments must not be NULL' USING ERRCODE='22023'; END IF;
    meta := splitjson._lookup(p_table,'SELECT');
    RETURN QUERY EXECUTE splitjson._find_query(meta,p_path) USING p_value,p_path;
END $$;

-- Installer-only: the same SQL used by find_ids, planned by PostgreSQL.
CREATE OR REPLACE FUNCTION splitjson.explain_find_ids(p_table regclass,p_path text[],p_value jsonb) RETURNS SETOF text
LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE;
BEGIN
    IF p_path IS NULL OR p_value IS NULL THEN RAISE EXCEPTION 'arguments must not be NULL' USING ERRCODE='22023'; END IF;
    meta := splitjson._lookup(p_table,'SELECT');
    RETURN QUERY EXECUTE 'EXPLAIN (COSTS OFF) ' || splitjson._find_query(meta,p_path) USING p_value,p_path;
END $$;

CREATE OR REPLACE FUNCTION splitjson._create_index(p_table regclass,p_name text,p_slot integer,p_kind text) RETURNS regclass
LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; parts text[]; qualified_name text; expression text;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    IF p_name IS NULL OR p_slot IS NULL OR p_slot NOT BETWEEN 1 AND jsonb_array_length(meta.paths) OR
       p_kind IS NULL OR p_kind NOT IN ('jsonb','text') THEN
        RAISE EXCEPTION 'invalid index name, slot or kind (jsonb/text)' USING ERRCODE='22023';
    END IF;
    parts := parse_ident(p_name,true);
    IF cardinality(parts)<>1 OR octet_length(parts[1])>63 THEN
        RAISE EXCEPTION 'use a single PostgreSQL index identifier' USING ERRCODE='22023';
    END IF;
    SELECT format('%I.%I',n.nspname,parts[1]) INTO qualified_name
        FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid=meta.storage_name::regclass;
    expression := format('hot_%s',p_slot);
    IF p_kind='text' THEN expression := format('(%s #>> %L::text[])',expression,'{}'); END IF;
    EXECUTE format('CREATE INDEX %I ON %s USING btree (%s)',parts[1],meta.storage_name,expression);
    RETURN qualified_name::regclass;
END $$;
REVOKE ALL ON FUNCTION splitjson._create_index(regclass,text,integer,text) FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson.create_path_index(p_table regclass,p_name text,p_path text[],p_kind text) RETURNS regclass
LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; candidates integer[];
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    IF p_path IS NULL THEN RAISE EXCEPTION 'path must not be NULL' USING ERRCODE='22023'; END IF;
    candidates := splitjson._path_candidates(meta.paths,p_path);
    IF cardinality(candidates)<>1 THEN
        RAISE EXCEPTION 'path must identify one registered slot; use a typed jsonb path for ambiguity' USING ERRCODE='22023';
    END IF;
    RETURN splitjson._create_index(p_table,p_name,candidates[1],p_kind);
END $$;

CREATE OR REPLACE FUNCTION splitjson.create_path_index(p_table regclass,p_name text,p_path text[]) RETURNS regclass
LANGUAGE sql SET search_path=pg_catalog, pg_temp
RETURN splitjson.create_path_index(p_table,p_name,p_path,'jsonb');

CREATE OR REPLACE FUNCTION splitjson.create_path_index(p_table regclass,p_name text,p_path jsonb,p_kind text DEFAULT 'jsonb') RETURNS regclass
LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; slot integer;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    IF p_path IS NULL THEN RAISE EXCEPTION 'path must not be NULL' USING ERRCODE='22023'; END IF;
    PERFORM splitjson.validate_paths(jsonb_build_array(p_path));
    SELECT ord::integer INTO slot FROM jsonb_array_elements(meta.paths) WITH ORDINALITY p(path,ord) WHERE path=p_path;
    IF slot IS NULL THEN RAISE EXCEPTION 'path must be registered' USING ERRCODE='22023'; END IF;
    RETURN splitjson._create_index(p_table,p_name,slot,p_kind);
END $$;

-- New-install and supported upgrade registration. Use canonical descriptors for
-- pg_dump round trips; OIDs are never stored in the dumped configuration table.
UPDATE splitjson._tables SET view_definition=splitjson._view_definition(to_regclass(view_name)),
    storage_definition=splitjson._storage_definition(to_regclass(storage_name));
ALTER TABLE splitjson._tables ALTER COLUMN view_definition SET NOT NULL;
ALTER TABLE splitjson._tables ALTER COLUMN storage_definition SET NOT NULL;
DO $$ DECLARE meta splitjson._tables%ROWTYPE; BEGIN
    FOR meta IN SELECT * FROM splitjson._tables LOOP PERFORM splitjson._validate_mapping(meta); END LOOP;
END $$;

CREATE EVENT TRIGGER splitjson_ddl_start ON ddl_command_start
    EXECUTE FUNCTION splitjson._ddl_start_guard();
CREATE EVENT TRIGGER splitjson_ddl_end ON ddl_command_end
    EXECUTE FUNCTION splitjson._ddl_end_guard();
CREATE EVENT TRIGGER splitjson_sql_drop ON sql_drop
    EXECUTE FUNCTION splitjson._sql_drop_guard();

CREATE OR REPLACE FUNCTION splitjson.grant_access(p_table regclass,p_role regrole,p_mode text)
RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; role_name name;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    SELECT rolname INTO role_name FROM pg_roles WHERE oid=p_role;
    IF role_name IS NULL OR p_mode IS NULL OR p_mode NOT IN ('read','write') THEN
        RAISE EXCEPTION 'use an existing role and mode read or write' USING ERRCODE='22023';
    END IF;
    EXECUTE format('GRANT USAGE ON SCHEMA splitjson,%I TO %I',
                   (parse_ident(meta.view_name,true))[1],role_name);
    EXECUTE format('GRANT SELECT ON %s TO %I',meta.view_name,role_name);
    EXECUTE format('GRANT EXECUTE ON FUNCTION splitjson.get_field(regclass,bigint,text[]),'
                   'splitjson.find_ids(regclass,text[],jsonb) TO %I',role_name);
    IF p_mode='write' THEN
        EXECUTE format('GRANT INSERT,UPDATE,DELETE ON %s TO %I',meta.view_name,role_name);
        EXECUTE format('GRANT EXECUTE ON FUNCTION splitjson.set_field(regclass,bigint,text[],jsonb,boolean),'
            'splitjson.set_fields(regclass,bigint,jsonb,boolean),splitjson.delete_field(regclass,bigint,text[]),'
            'splitjson.increment_field(regclass,bigint,text[],numeric) TO %I',role_name);
    END IF;
END $$;

-- Scope ACL changes to this extension, not unrelated functions in the schema.
DO $$ DECLARE signature text; grantee_name text; BEGIN
    FOR signature,grantee_name IN SELECT p.oid::regprocedure::text,
        CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(r.rolname) END
        FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
        LEFT JOIN pg_roles r ON r.oid=a.grantee JOIN pg_depend d
        ON d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e'
        JOIN pg_extension e ON d.refclassid='pg_extension'::regclass AND d.refobjid=e.oid
        WHERE e.extname='pg_splitjson' AND a.grantee<>p.proowner
    LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %s CASCADE',signature,grantee_name); END LOOP;
    PERFORM splitjson._secure_relation('splitjson._tables');
    PERFORM splitjson._secure_relation('splitjson._table_id_seq');
END $$;
DO $$ DECLARE relation text; grantee_name text; BEGIN
    FOR relation IN SELECT storage_name FROM splitjson._tables LOOP
        PERFORM splitjson._secure_relation(relation::regclass);
    END LOOP;
    FOR grantee_name IN SELECT CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(r.rolname) END
        FROM pg_namespace n CROSS JOIN LATERAL aclexplode(n.nspacl) a
        LEFT JOIN pg_roles r ON r.oid=a.grantee
        WHERE n.oid='splitjson_storage'::regnamespace AND a.grantee<>n.nspowner
    LOOP EXECUTE format('REVOKE ALL ON SCHEMA splitjson_storage FROM %s CASCADE',grantee_name); END LOOP;
END $$;
-- Views execute these pure functions as the querying role; no private access.
GRANT EXECUTE ON FUNCTION splitjson.cold_in(cstring),splitjson.cold_out(splitjson.cold),
    splitjson.cold_send(splitjson.cold),splitjson.cold_recv(internal),
    splitjson.restore(splitjson.cold,jsonb[]),splitjson.restore(splitjson.cold,jsonb[],jsonb) TO PUBLIC;

COMMENT ON EXTENSION pg_splitjson IS 'PostgreSQL Split JSON Storage Extension';
COMMENT ON FUNCTION splitjson.grant_access(regclass,regrole,text) IS 'Installer grants view privileges and minimal read/write API execution; never private storage';
COMMENT ON FUNCTION splitjson.index_ddl(regclass,text,jsonb,text,boolean) IS 'Return reviewed concurrent index DDL; execute separately outside a transaction';
COMMENT ON TYPE splitjson.cold IS 'Version 2 cold envelope (reads v1); PG18 physical format, logical migration across major versions';


