CREATE OR REPLACE FUNCTION splitjson._qualified_name(p_table regclass) RETURNS text
LANGUAGE sql STABLE STRICT SET search_path=pg_catalog, pg_temp
RETURN (SELECT format('%I.%I',n.nspname,c.relname) FROM pg_class c
        JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid=p_table);

CREATE OR REPLACE FUNCTION splitjson._view_definition(p_table regclass) RETURNS text
LANGUAGE sql STABLE STRICT SET search_path=pg_catalog, pg_temp
RETURN pg_get_viewdef(p_table,true);

CREATE OR REPLACE FUNCTION splitjson._secure_relation(p_table regclass) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE grantee_name text;
BEGIN
    FOR grantee_name IN SELECT CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(r.rolname) END
        FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a
        LEFT JOIN pg_roles r ON r.oid=a.grantee WHERE c.oid=p_table AND a.grantee<>c.relowner
    LOOP EXECUTE format('REVOKE ALL ON %s FROM %s CASCADE',p_table,grantee_name); END LOOP;
END $$;

CREATE OR REPLACE FUNCTION splitjson._storage_definition(p_table regclass) RETURNS jsonb
LANGUAGE sql STABLE STRICT SET search_path=pg_catalog, pg_temp
RETURN (SELECT jsonb_agg(jsonb_build_object('name',attname,'type',format_type(atttypid,atttypmod),
                'collation',attcollation::regcollation::text,'generated',attgenerated,'identity',attidentity,'not_null',attnotnull,'storage',attstorage)
                ORDER BY attnum)
        FROM pg_attribute WHERE attrelid=p_table AND attnum>0 AND NOT attisdropped);

UPDATE splitjson._tables SET storage_definition=splitjson._storage_definition(storage_name::regclass);

CREATE FUNCTION splitjson._replication_fingerprint(p_meta splitjson._tables) RETURNS text
LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog,pg_temp
RETURN md5('0.3.0:'||p_meta.storage_definition::text||p_meta.paths::text||p_meta.business_columns::text||p_meta.storage_mode||coalesce(p_meta.partition_spec::text,''));

-- A path segment naming an array element must be an integer when it is
-- traversed below an existing object path.  jsonb #- has a subtle edge case:
-- applying a non-integer segment to an array at the root is a no-op, while the
-- same segment after an object key raises 22P02.  Fast delete paths start at a
-- hot subtree, so inspect that subtree before using the short update.  This
-- keeps the short path cold-free while preserving native JSONB errors.
CREATE OR REPLACE FUNCTION splitjson._array_path_requires_fallback(p_value jsonb,p_path text[])
RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog, pg_temp
AS $$
DECLARE cursor jsonb := p_value; i integer; segment text;
BEGIN
    FOR i IN 1..cardinality(p_path) LOOP
        segment := p_path[i];
        IF jsonb_typeof(cursor)='array' AND segment !~ '^[[:space:]]*[+-]?[0-9]+$' THEN
            RETURN true;
        END IF;
        cursor := cursor #> ARRAY[segment];
        IF cursor IS NULL THEN RETURN false; END IF;
    END LOOP;
    RETURN false;
END $$;

CREATE OR REPLACE FUNCTION splitjson._policy_definition(p_storage regclass) RETURNS jsonb
LANGUAGE sql STABLE SET search_path=pg_catalog,pg_temp
RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,
    'permissive',p.polpermissive,'roles',(SELECT jsonb_agg(CASE WHEN x=0 THEN 'public' ELSE pg_get_userbyid(x)::text END ORDER BY x) FROM unnest(p.polroles) x),
    'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY p.polname COLLATE "C")
    FROM pg_policy p WHERE p.polrelid=p_storage),'[]'::jsonb);

CREATE OR REPLACE FUNCTION splitjson._validate_mapping(p_meta splitjson._tables) RETURNS void
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,pg_temp
AS $$
DECLARE v oid; s oid; installer oid; hot_count integer; expected_count integer; leaf record;
BEGIN
    v:=to_regclass(p_meta.view_name); s:=to_regclass(p_meta.storage_name);
    SELECT extowner INTO installer FROM pg_extension WHERE extname='pg_splitjson';
    IF EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a
        WHERE n.nspname='splitjson_storage' AND a.grantee<>installer) OR
       EXISTS(SELECT 1 FROM pg_namespace WHERE nspname IN ('splitjson','splitjson_storage') AND nspowner<>installer) OR
       EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a
        WHERE n.nspname='splitjson' AND a.grantee<>installer AND a.privilege_type='CREATE') THEN
        RAISE EXCEPTION 'private schema ownership or ACL has drifted' USING ERRCODE='55000'; END IF;
    IF v IS NULL OR s IS NULL OR
       NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=v AND relkind='v' AND relowner=installer
          AND reloptions @> ARRAY['security_barrier=true'] AND
          coalesce(reloptions @> ARRAY['security_invoker=true'],false)=p_meta.rls_enabled) OR
       NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=s AND relkind=CASE WHEN p_meta.storage_mode='heap' THEN 'r'::"char" ELSE 'p'::"char" END
          AND relowner=installer AND relpersistence='p' AND relnamespace=to_regnamespace('splitjson_storage')
          AND relrowsecurity=p_meta.rls_enabled AND relforcerowsecurity=p_meta.rls_force) THEN
        RAISE EXCEPTION 'invalid managed relation, ownership, RLS or storage layout: %',p_meta.view_name USING ERRCODE='55000';
    END IF;
    IF EXISTS(SELECT 1 FROM splitjson._jobs j WHERE j.source_name=p_meta.view_name AND j.state NOT IN ('completed','aborted') AND
        (j.source_epoch<>p_meta.layout_epoch OR j.source_fingerprint<>splitjson._capture_fingerprint(p_meta))) THEN
        RAISE EXCEPTION 'active migration source definition has drifted' USING ERRCODE='55000'; END IF;
    IF EXISTS(SELECT 1 FROM splitjson._replicas r WHERE r.view_name=p_meta.view_name AND r.state NOT IN ('detached','promoted') AND
       (r.fingerprint<>splitjson._replication_fingerprint(p_meta) OR (r.detail ? 'source_fingerprint' AND r.detail->>'source_fingerprint'<>splitjson._capture_fingerprint(p_meta)))) THEN
        RAISE EXCEPTION 'active replication layout/security definition has drifted' USING ERRCODE='55000'; END IF;
    PERFORM splitjson.validate_paths(p_meta.paths);
    hot_count:=jsonb_array_length(p_meta.paths);
    expected_count:=3+hot_count+(SELECT count(*) FROM jsonb_object_keys(p_meta.business_columns));
    IF hot_count=0 OR jsonb_array_length(p_meta.storage_definition) IS DISTINCT FROM expected_count OR
       (p_meta.storage_mode<>'heap' AND NOT EXISTS(SELECT 1 FROM pg_partitioned_table WHERE partrelid=s AND partnatts=1 AND partattrs[0]=1 AND
            partstrat=CASE WHEN p_meta.storage_mode='hash' THEN 'h'::"char" ELSE 'r'::"char" END)) OR
       splitjson._storage_definition(s) IS DISTINCT FROM p_meta.storage_definition OR
       splitjson._view_definition(v) IS DISTINCT FROM p_meta.view_definition OR
       NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=s AND attnum=1 AND attname='id' AND atttypid='int8'::regtype AND attnotnull) OR
       NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=s AND attnum=2 AND attname='cold' AND atttypid='splitjson.cold'::regtype AND attnotnull AND attstorage='e') OR
       NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=s AND attname='row_revision' AND atttypid='int8'::regtype AND attnotnull) OR
       NOT EXISTS(SELECT 1 FROM pg_index WHERE indrelid=s AND indisprimary AND indisvalid AND indnkeyatts=1 AND indkey[0]=1) OR
       NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=v AND tgname='pg_splitjson_write' AND tgfoid='splitjson._view_write()'::regprocedure AND tgenabled='O' AND tgtype=93) OR
       NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=s AND tgname=format('pg_splitjson_revision_%s',md5(p_meta.storage_name))
          AND tgfoid='splitjson._revision_write()'::regprocedure AND tgenabled='O' AND tgtype=23) OR
       NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=s AND tgname='pg_splitjson_fence'
          AND tgfoid='splitjson._storage_write_guard()'::regprocedure AND tgenabled='O' AND tgtype=62) OR
       EXISTS(SELECT 1 FROM generate_series(1,hot_count) i WHERE NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=s AND attname='hot_'||i AND atttypid='jsonb'::regtype AND NOT attisdropped)) OR
       EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.oid=s AND a.grantee<>installer) OR
       EXISTS(SELECT 1 FROM pg_attribute t CROSS JOIN LATERAL aclexplode(t.attacl) a WHERE t.attrelid=s AND a.grantee<>installer) OR
       splitjson._policy_definition(s) IS DISTINCT FROM p_meta.policy_definition OR
       (p_meta.revision_initialized AND NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_sequence q ON q.seqrelid=c.oid WHERE c.oid=to_regclass(p_meta.revision_sequence)
          AND c.relowner=installer AND c.relnamespace='splitjson'::regnamespace AND NOT q.seqcycle AND q.seqincrement=1 AND q.seqmin=1 AND q.seqtypid='int8'::regtype)) OR
       EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.oid=to_regclass(p_meta.revision_sequence) AND a.grantee<>installer) THEN
        RAISE EXCEPTION 'managed mapping has drifted: %; restore its layout before use',p_meta.view_name USING ERRCODE='55000';
    END IF;
    IF EXISTS(SELECT 1 FROM splitjson._slot_types t WHERE t.view_name=p_meta.view_name AND NOT EXISTS(SELECT 1 FROM pg_constraint c WHERE c.conrelid=s AND c.conname=t.guard_name AND c.convalidated AND pg_get_constraintdef(c.oid,true)=t.definition)) THEN
        RAISE EXCEPTION 'managed path type guard has drifted' USING ERRCODE='55000'; END IF;
    -- Dropping an index is allowed. Remove stale registrations in the DDL guard;
    -- live registrations must retain their canonical definition.
    IF EXISTS(SELECT 1 FROM splitjson._path_indexes i WHERE i.view_name=p_meta.view_name AND to_regclass(i.index_name) IS NOT NULL AND pg_get_indexdef(to_regclass(i.index_name)) IS DISTINCT FROM i.definition) THEN
        RAISE EXCEPTION 'managed path index has drifted' USING ERRCODE='55000'; END IF;
    FOR leaf IN SELECT l.*,c.oid,c.relowner,c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.relacl,c.relnamespace FROM splitjson._leaves l
        LEFT JOIN pg_class c ON c.oid=to_regclass(l.relation_name) WHERE l.view_name=p_meta.view_name LOOP
        IF leaf.oid IS NULL OR leaf.relowner<>installer OR leaf.relkind<>'r' OR leaf.relrowsecurity OR leaf.relforcerowsecurity OR
           leaf.relnamespace<>to_regnamespace('splitjson_storage') OR
           NOT EXISTS(SELECT 1 FROM pg_inherits WHERE inhparent=s AND inhrelid=leaf.oid) OR
           splitjson._storage_definition(leaf.oid) IS DISTINCT FROM p_meta.storage_definition OR
           (SELECT pg_get_expr(relpartbound,oid) FROM pg_class WHERE oid=leaf.oid) IS DISTINCT FROM leaf.bound OR
           splitjson._partition_bound(leaf.oid) IS DISTINCT FROM leaf.bound_spec OR
           EXISTS(SELECT 1 FROM aclexplode(leaf.relacl) a WHERE a.grantee<>installer) OR
           EXISTS(SELECT 1 FROM pg_attribute t CROSS JOIN LATERAL aclexplode(t.attacl) a WHERE t.attrelid=leaf.oid AND a.grantee<>installer) OR
           NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=leaf.oid AND tgname=format('pg_splitjson_revision_%s',md5(p_meta.storage_name)) AND
                tgfoid='splitjson._revision_write()'::regprocedure AND tgenabled='O' AND tgtype=23) OR
           NOT EXISTS(SELECT 1 FROM pg_index WHERE indrelid=leaf.oid AND indisprimary AND indisvalid AND indnkeyatts=1 AND indkey[0]=1) OR
           EXISTS(SELECT 1 FROM pg_inherits WHERE inhparent=leaf.oid) OR
           EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=leaf.oid) THEN
            RAISE EXCEPTION 'managed partition has drifted: %',leaf.relation_name USING ERRCODE='55000';
        END IF;
    END LOOP;
    IF (SELECT count(*) FROM pg_inherits WHERE inhparent=s)<>(SELECT count(*) FROM splitjson._leaves WHERE view_name=p_meta.view_name) THEN
        RAISE EXCEPTION 'unregistered partition attached to %',p_meta.view_name USING ERRCODE='55000'; END IF;
END $$;

CREATE OR REPLACE FUNCTION splitjson._api_storage_relation(p_table regclass) RETURNS regclass
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    RETURN meta.storage_name::regclass;
END $$;

CREATE OR REPLACE FUNCTION splitjson.storage_relation(p_table regclass) RETURNS regclass
LANGUAGE C STABLE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._api_check_table(p_table regclass,p_check_data boolean DEFAULT false)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; rows_checked bigint := 0; invalid_indexes bigint;
BEGIN
    IF p_check_data IS NULL THEN RAISE EXCEPTION 'check_data must not be NULL' USING ERRCODE='22023'; END IF;
    meta := splitjson._lookup(p_table,'SELECT');
    IF p_check_data THEN
        EXECUTE format('SELECT count(splitjson.restore(cold,%s,$1)) FROM %s',
                       splitjson._hot_array(meta.paths),meta.storage_name) INTO rows_checked USING meta.paths;
    END IF;
    SELECT count(*) INTO invalid_indexes FROM pg_index
        WHERE indrelid IN (SELECT meta.storage_name::regclass UNION ALL SELECT to_regclass(relation_name) FROM splitjson._leaves WHERE view_name=meta.view_name)
        AND (NOT indisvalid OR NOT indisready);
    RETURN jsonb_build_object('view',meta.view_name,'storage',meta.storage_name,
               'layout_ok',true,'rows_checked',rows_checked,'invalid_indexes',invalid_indexes);
END $$;

CREATE OR REPLACE FUNCTION splitjson.check_table(p_table regclass,p_check_data boolean DEFAULT false)
RETURNS jsonb
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._api_check_all(p_check_data boolean DEFAULT false) RETURNS SETOF jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE relation text;
BEGIN
    FOR relation IN SELECT view_name FROM splitjson._tables ORDER BY view_name LOOP
        RETURN NEXT splitjson.check_table(relation::regclass,p_check_data);
    END LOOP;
END $$;

CREATE OR REPLACE FUNCTION splitjson.check_all(p_check_data boolean DEFAULT false) RETURNS SETOF jsonb
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._api_table_stats(p_table regclass) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; stats jsonb;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    SELECT to_jsonb(s) || jsonb_build_object('view',meta.view_name,
        'total_bytes',pg_total_relation_size(s.relid),'heap_bytes',pg_relation_size(s.relid),
        'indexes_bytes',pg_indexes_size(s.relid)) INTO stats
        FROM pg_stat_user_tables s WHERE relid=meta.storage_name::regclass;
    RETURN stats;
END $$;

CREATE OR REPLACE FUNCTION splitjson.table_stats(p_table regclass) RETURNS jsonb
LANGUAGE C STABLE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._api_rename_table(p_table regclass,p_name text) RETURNS regclass
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; parts text[]; oldparts text[]; target text;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    PERFORM splitjson._assert_idle(p_table);
    parts := parse_ident(p_name,true); oldparts := parse_ident(meta.view_name,true);
    IF cardinality(parts)<>2 OR parts[1]<>oldparts[1] OR octet_length(parts[2])>63 THEN
        RAISE EXCEPTION 'use a schema-qualified name in the same business schema' USING ERRCODE='22023';
    END IF;
    target := format('%I.%I',parts[1],parts[2]);
    IF to_regclass(target) IS NOT NULL THEN RAISE EXCEPTION 'target already exists' USING ERRCODE='42P07'; END IF;
    UPDATE splitjson._tables SET view_name=target WHERE view_name=meta.view_name;
    EXECUTE format('ALTER VIEW %s RENAME TO %I',meta.view_name,parts[2]);
    RETURN target::regclass;
END $$;

CREATE OR REPLACE FUNCTION splitjson.rename_table(p_table regclass,p_name text) RETURNS regclass
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._api_set_business_not_null(p_table regclass,p_column text,p_enabled boolean DEFAULT true)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; slot integer;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT'); PERFORM splitjson._assert_idle(p_table);
    -- Use the same C ordering as create_table, not jsonb key-length ordering.
    SELECT n INTO slot FROM (SELECT key,row_number() OVER (ORDER BY key COLLATE "C")::integer n
                            FROM jsonb_each_text(meta.business_columns)) c WHERE key=p_column;
    IF slot IS NULL OR p_enabled IS NULL THEN RAISE EXCEPTION 'unknown business column or NULL flag' USING ERRCODE='22023'; END IF;
    EXECUTE format('ALTER TABLE %s ALTER COLUMN extra_%s %s NOT NULL',
                   meta.storage_name,slot,CASE WHEN p_enabled THEN 'SET' ELSE 'DROP' END);
    UPDATE splitjson._tables SET storage_definition=splitjson._storage_definition(meta.storage_name::regclass),view_definition=splitjson._view_definition(meta.view_name::regclass)
        WHERE view_name=meta.view_name;
END $$;

CREATE OR REPLACE FUNCTION splitjson.set_business_not_null(p_table regclass,p_column text,p_enabled boolean DEFAULT true)
RETURNS void
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._api_set_business_default(p_table regclass,p_column text,p_value jsonb)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; slot integer; declaration text; literal text;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT'); PERFORM splitjson._assert_idle(p_table);
    SELECT n,value INTO slot,declaration FROM (SELECT key,value,
        row_number() OVER (ORDER BY key COLLATE "C")::integer n FROM jsonb_each_text(meta.business_columns)) c
        WHERE key=p_column;
    IF slot IS NULL THEN RAISE EXCEPTION 'unknown business column' USING ERRCODE='22023'; END IF;
    IF p_value IS NULL THEN
        EXECUTE format('ALTER TABLE %s ALTER COLUMN extra_%s DROP DEFAULT',meta.storage_name,slot);
        EXECUTE format('ALTER VIEW %s ALTER COLUMN %I DROP DEFAULT',meta.view_name,p_column);
    ELSE
        EXECUTE format('SELECT ((jsonb_populate_record(NULL::%s,$1)).%I)::text',meta.view_name,p_column)
            INTO literal USING jsonb_build_object(p_column,p_value);
        EXECUTE format('ALTER TABLE %s ALTER COLUMN extra_%s SET DEFAULT %L::%s',meta.storage_name,slot,literal,declaration);
        EXECUTE format('ALTER VIEW %s ALTER COLUMN %I SET DEFAULT %L::%s',meta.view_name,p_column,literal,declaration);
    END IF;
    UPDATE splitjson._tables SET storage_definition=splitjson._storage_definition(meta.storage_name::regclass),view_definition=splitjson._view_definition(meta.view_name::regclass)
        WHERE view_name=meta.view_name;
END $$;

CREATE OR REPLACE FUNCTION splitjson.set_business_default(p_table regclass,p_column text,p_value jsonb)
RETURNS void
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._api_add_field_check(p_table regclass,p_name text,p_path jsonb,
                                                    p_type text,p_required boolean DEFAULT false)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; slot integer; condition text; parts text[];
BEGIN
    meta := splitjson._lookup(p_table,'SELECT'); PERFORM splitjson._assert_idle(p_table);
    PERFORM splitjson.validate_paths(jsonb_build_array(p_path));
    parts := parse_ident(p_name,true);
    IF p_type IS NULL OR p_required IS NULL OR cardinality(parts)<>1 OR octet_length(parts[1])>63 OR
       p_type NOT IN ('object','array','string','number','boolean','null') THEN
        RAISE EXCEPTION 'invalid check name or JSON type' USING ERRCODE='22023';
    END IF;
    SELECT ord::integer INTO slot FROM jsonb_array_elements(meta.paths) WITH ORDINALITY p(path,ord) WHERE path=p_path;
    IF slot IS NULL THEN RAISE EXCEPTION 'check path must be a registered hot slot' USING ERRCODE='22023'; END IF;
    condition := format('jsonb_typeof(hot_%s)=%L',slot,p_type);
    IF p_required THEN condition := format('hot_%s IS NOT NULL AND (%s)',slot,condition); END IF;
    EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I CHECK (%s)',meta.storage_name,parts[1],condition);
    INSERT INTO splitjson._field_checks VALUES(meta.view_name,parts[1],p_path,p_type,p_required);
END $$;

CREATE OR REPLACE FUNCTION splitjson.add_field_check(p_table regclass,p_name text,p_path jsonb,
                                                    p_type text,p_required boolean DEFAULT false)
RETURNS void
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._api_index_ddl(p_table regclass,p_name text,p_path jsonb,
                                             p_kind text DEFAULT 'jsonb',p_unique boolean DEFAULT false)
RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; slot integer; parts text[]; expression text;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    PERFORM splitjson.validate_paths(jsonb_build_array(p_path));
    parts := parse_ident(p_name,true);
    IF p_kind IS NULL OR p_unique IS NULL OR cardinality(parts)<>1 OR octet_length(parts[1])>63 OR
       p_kind NOT IN ('jsonb','text') THEN RAISE EXCEPTION 'invalid index declaration' USING ERRCODE='22023'; END IF;
    SELECT ord::integer INTO slot FROM jsonb_array_elements(meta.paths) WITH ORDINALITY p(path,ord) WHERE path=p_path;
    IF slot IS NULL THEN RAISE EXCEPTION 'path must be a registered hot slot' USING ERRCODE='22023'; END IF;
    expression := format('hot_%s',slot);
    IF p_kind='text' THEN expression := format('(%s #>> %L::text[])',expression,'{}'); END IF;
    RETURN format('CREATE %sINDEX CONCURRENTLY %I ON %s USING btree (%s);',
                  CASE WHEN p_unique THEN 'UNIQUE ' ELSE '' END,parts[1],meta.storage_name,expression);
END $$;

CREATE OR REPLACE FUNCTION splitjson.index_ddl(p_table regclass,p_name text,p_path jsonb,
                                             p_kind text DEFAULT 'jsonb',p_unique boolean DEFAULT false)
RETURNS text
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._ddl_end_guard() RETURNS event_trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE;
BEGIN
    IF to_regclass('splitjson._tables') IS NULL OR splitjson._ddl_scope() THEN RETURN; END IF;
    FOR meta IN SELECT * FROM splitjson._tables LOOP PERFORM splitjson._validate_mapping(meta); END LOOP;
END $$;

CREATE OR REPLACE FUNCTION splitjson._sql_drop_guard() RETURNS event_trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
BEGIN
    IF to_regclass('splitjson._tables') IS NULL OR splitjson._ddl_scope() THEN RETURN; END IF;
    IF EXISTS(SELECT 1 FROM pg_event_trigger_dropped_objects() d JOIN splitjson._tables m
        ON format('%I.%I',d.schema_name,d.object_name) IN (m.view_name,m.storage_name)
        WHERE d.object_type IN ('table','view')) THEN
        RAISE EXCEPTION 'use splitjson.drop_table to remove managed relations' USING ERRCODE='55000';
    END IF;
END $$;

CREATE OR REPLACE FUNCTION splitjson._ddl_start_guard() RETURNS event_trigger
AS 'MODULE_PATHNAME','pg_splitjson_ddl_start_guard' LANGUAGE C SECURITY DEFINER SET search_path=pg_catalog, pg_temp;

CREATE FUNCTION splitjson._api_reinitialize_table(p_table regclass,p_reason text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; maximum bigint; sequence_value bigint; epoch text;
BEGIN
    m:=splitjson._lookup(p_table,'SELECT');
    IF p_reason IS NULL OR p_reason NOT IN ('restore','recovery','import','takeover') THEN
        RAISE EXCEPTION 'reason must be restore, recovery, import or takeover' USING ERRCODE='22023'; END IF;
    EXECUTE format('LOCK TABLE %s IN ACCESS EXCLUSIVE MODE',m.storage_name);
    IF to_regclass(m.revision_sequence) IS NULL THEN
        EXECUTE format('CREATE SEQUENCE %s NO CYCLE',m.revision_sequence);
        PERFORM splitjson._secure_relation(m.revision_sequence::regclass);
    END IF;
    EXECUTE format('SELECT coalesce(max(row_revision),0) FROM %s',m.storage_name) INTO maximum;
    EXECUTE format('SELECT last_value FROM %s',m.revision_sequence) INTO sequence_value;
    PERFORM setval(m.revision_sequence::regclass,greatest(maximum,sequence_value,1),true);
    epoch:=splitjson._new_epoch();
    UPDATE splitjson._tables SET layout_epoch=epoch,layout_generation=layout_generation+1,revision_initialized=true WHERE view_name=m.view_name;
    RETURN epoch;
END $$;

CREATE OR REPLACE FUNCTION splitjson.reinitialize_table(p_table regclass,p_reason text) RETURNS text
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE FUNCTION splitjson._api_set_business_collation(p_table regclass,p_column text,p_collation name) RETURNS regclass
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; n integer; declaration text; coll regcollation; qualified text; select_columns text:=''; key text;
    view_acl jsonb; column_acl jsonb; defaults jsonb; item jsonb; target regclass;
BEGIN
    m:=splitjson._lookup(p_table,'SELECT'); PERFORM splitjson._assert_idle(p_table);
    SELECT x.i,x.value INTO n,declaration FROM (SELECT e.key,e.value,row_number() OVER(ORDER BY e.key COLLATE "C")::integer i FROM jsonb_each_text(m.business_columns) e) x WHERE x.key=p_column;
    coll:=splitjson._collation(p_collation);
    IF n IS NULL OR coll IS NULL THEN RAISE EXCEPTION 'business column and collation required' USING ERRCODE='22023'; END IF;
    SELECT format('%I.%I',ns.nspname,c.collname) INTO qualified FROM pg_collation c JOIN pg_namespace ns ON ns.oid=c.collnamespace WHERE c.oid=coll;
    SELECT coalesce(jsonb_agg(jsonb_build_object('role',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END,'privilege',a.privilege_type,'grantable',a.is_grantable)),'[]') INTO view_acl
        FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.oid=p_table AND a.grantee<>c.relowner;
    SELECT coalesce(jsonb_agg(jsonb_build_object('role',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END,'privilege',a.privilege_type,'grantable',a.is_grantable,'column',t.attname)),'[]') INTO column_acl
        FROM pg_attribute t CROSS JOIN LATERAL aclexplode(t.attacl) a WHERE t.attrelid=p_table;
    SELECT coalesce(jsonb_agg(jsonb_build_object('column',a.attname,'expression',pg_get_expr(d.adbin,d.adrelid))),'[]') INTO defaults
        FROM pg_attrdef d JOIN pg_attribute a ON a.attrelid=d.adrelid AND a.attnum=d.adnum WHERE d.adrelid=p_table;
    -- External view dependents cause an atomic error, never DROP CASCADE.
    EXECUTE format('DROP VIEW %s',m.view_name);
    EXECUTE format('ALTER TABLE %s ALTER COLUMN extra_%s TYPE %s COLLATE %s',m.storage_name,n,declaration,qualified);
    n:=0;
    FOR key IN SELECT e.key FROM jsonb_each(m.business_columns) e ORDER BY e.key COLLATE "C" LOOP
        n:=n+1; select_columns:=select_columns||format(',extra_%s AS %I',n,key); END LOOP;
    EXECUTE format('CREATE VIEW %s WITH (security_barrier=true,security_invoker=%s) AS SELECT id,splitjson.restore(cold,%s,%L::jsonb) AS doc%s FROM %s',m.view_name,
        CASE WHEN m.rls_enabled THEN 'true' ELSE 'false' END,splitjson._hot_array(m.paths),m.paths,select_columns,m.storage_name);
    EXECUTE format('CREATE TRIGGER pg_splitjson_write INSTEAD OF INSERT OR UPDATE OR DELETE ON %s FOR EACH ROW EXECUTE FUNCTION splitjson._view_write()',m.view_name);
    target:=m.view_name::regclass;
    FOR item IN SELECT value FROM jsonb_array_elements(view_acl) LOOP
        EXECUTE format('GRANT %s ON %s TO %s%s',item->>'privilege',m.view_name,item->>'role',CASE WHEN (item->>'grantable')::boolean THEN ' WITH GRANT OPTION' ELSE '' END); END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(column_acl) LOOP
        EXECUTE format('GRANT %s(%I) ON %s TO %s%s',item->>'privilege',item->>'column',m.view_name,item->>'role',CASE WHEN (item->>'grantable')::boolean THEN ' WITH GRANT OPTION' ELSE '' END); END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(defaults) LOOP
        EXECUTE format('ALTER VIEW %s ALTER COLUMN %I SET DEFAULT %s',m.view_name,item->>'column',item->>'expression'); END LOOP;
    UPDATE splitjson._tables SET view_definition=splitjson._view_definition(target),storage_definition=splitjson._storage_definition(m.storage_name::regclass) WHERE view_name=m.view_name;
    RETURN target;
END $$;

CREATE OR REPLACE FUNCTION splitjson.set_business_collation(p_table regclass,p_column text,p_collation name) RETURNS regclass
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._hot_array(p_paths jsonb) RETURNS text
LANGUAGE sql IMMUTABLE STRICT SET search_path = pg_catalog, pg_temp
RETURN (SELECT 'ARRAY[' || string_agg(format('hot_%s', n), ',') || ']::jsonb[]'
        FROM generate_series(1, jsonb_array_length(p_paths)) AS n);

CREATE OR REPLACE FUNCTION splitjson._assignments(p_paths jsonb) RETURNS text
LANGUAGE sql IMMUTABLE STRICT SET search_path = pg_catalog, pg_temp
RETURN (SELECT string_agg(format('hot_%s=($2)[%s]', n, n), ',')
        FROM generate_series(1, jsonb_array_length(p_paths)) AS n);

CREATE OR REPLACE FUNCTION splitjson._lookup(p_table regclass, p_privilege text)
RETURNS splitjson._tables LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE;
BEGIN
    IF p_table IS NULL THEN RAISE EXCEPTION 'table must not be NULL' USING ERRCODE='22023'; END IF;
    SELECT * INTO meta FROM splitjson._tables WHERE view_name=splitjson._qualified_name(p_table);
    IF NOT FOUND THEN
        RAISE EXCEPTION 'relation is not a pg_splitjson managed view' USING ERRCODE='22023';
    END IF;
    IF NOT splitjson._management_target(p_table) AND (NOT has_column_privilege(splitjson._caller(),p_table,'doc',p_privilege) OR
       (p_privilege='SELECT' AND NOT has_column_privilege(splitjson._caller(),p_table,'id','SELECT'))) THEN
        RAISE EXCEPTION 'permission denied for JSON %',lower(p_privilege) USING ERRCODE='42501';
    END IF;
    PERFORM splitjson._validate_mapping(meta);
    IF p_privilege IN ('INSERT','UPDATE','DELETE') AND (meta.follower_mode OR meta.write_fenced) THEN RAISE EXCEPTION 'replica is read only' USING ERRCODE='25006'; END IF;
    IF NOT has_schema_privilege(splitjson._caller(), (SELECT relnamespace FROM pg_class WHERE oid=p_table), 'USAGE') THEN
        RAISE EXCEPTION 'permission denied for business schema' USING ERRCODE='42501';
    END IF;
    RETURN meta;
END $$;
REVOKE ALL ON FUNCTION splitjson._lookup(regclass,text) FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson._slot(p_paths jsonb,p_path text[]) RETURNS integer
LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog, pg_temp
RETURN (SELECT ord::integer FROM jsonb_array_elements(p_paths) WITH ORDINALITY AS p(path,ord)
        WHERE path=to_jsonb(p_path));

CREATE OR REPLACE FUNCTION splitjson._save(p_storage text, p_id bigint, p_doc jsonb, p_paths jsonb)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
AS $$
DECLARE affected bigint;
BEGIN
    IF p_doc IS NULL THEN
        RAISE EXCEPTION 'doc must not be SQL NULL; JSON null is allowed' USING ERRCODE = '23502';
    END IF;
    PERFORM id FROM splitjson._query(format('UPDATE %s SET cold=$1,%s WHERE id=$3 RETURNING id',p_storage,splitjson._assignments(p_paths)),
        ARRAY['splitjson.cold','jsonb[]','bigint']::regtype[],
        ARRAY[splitjson.pack(p_doc,p_paths)::text,splitjson.slots(p_doc,p_paths)::text,p_id::text],false) AS q(id bigint);
    GET DIAGNOSTICS affected = ROW_COUNT;
    RETURN affected = 1;
END $$;
REVOKE ALL ON FUNCTION splitjson._save(text,bigint,jsonb,jsonb) FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson._api__view_write() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    meta splitjson._tables%ROWTYPE;
    hot_columns text;
    hot_params text;
    n integer;
    row_matches boolean;
    affected bigint;
    column_name text;
    column_type text;
    extra_columns text := '';
    extra_values text := '';
    extra_assignments text := '';
BEGIN
    SELECT * INTO STRICT meta FROM splitjson._tables WHERE view_name=splitjson._qualified_name(TG_RELID);
    PERFORM splitjson._validate_mapping(meta);
    IF meta.follower_mode OR meta.write_fenced THEN RAISE EXCEPTION 'replica is read only' USING ERRCODE='25006'; END IF;
    n := 0;
    FOR column_name,column_type IN SELECT key,value FROM jsonb_each_text(meta.business_columns) ORDER BY key COLLATE "C" LOOP
        n := n+1;
        extra_columns := extra_columns || format(',extra_%s',n);
        extra_values := extra_values || format(',($4::%s).%I',meta.view_name,column_name);
        extra_assignments := extra_assignments || format(',extra_%s=($5::%s).%I',n,meta.view_name,column_name);
    END LOOP;
    IF TG_OP <> 'INSERT' THEN
        SELECT q.value INTO row_matches FROM splitjson._query(
            format('SELECT ROW(id,splitjson.restore(cold,%s)%s)::%s IS NOT DISTINCT FROM $2 FROM %s WHERE id=$1 FOR UPDATE',splitjson._hot_array(meta.paths),extra_columns,meta.view_name,meta.storage_name),
            ARRAY['bigint'::regtype,meta.view_name::regtype],ARRAY[OLD.id::text,OLD::text],false) AS q(value boolean);
        GET DIAGNOSTICS affected = ROW_COUNT;
        IF affected = 0 THEN RETURN NULL; END IF;
        -- An INSTEAD OF trigger cannot re-evaluate the original UPDATE/DELETE
        -- expression like the heap executor's EvalPlanQual. Require a retry.
        IF row_matches IS DISTINCT FROM true THEN
            RAISE EXCEPTION 'concurrent row modification; retry the statement or transaction'
                USING ERRCODE = '40001';
        END IF;
    END IF;
    IF TG_OP = 'DELETE' THEN
        PERFORM id FROM splitjson._query(format('DELETE FROM %s WHERE id=$1 RETURNING id',meta.storage_name),
            ARRAY['bigint']::regtype[],ARRAY[OLD.id::text],false) AS q(id bigint);
        RETURN OLD;
    END IF;
    IF NEW.id IS NULL OR NEW.doc IS NULL THEN
        RAISE EXCEPTION 'id and doc must not be SQL NULL' USING ERRCODE = '23502';
    END IF;
    IF TG_OP = 'INSERT' THEN
        FOR n IN 1..jsonb_array_length(meta.paths) LOOP
            hot_columns := concat_ws(',', hot_columns, format('hot_%s', n));
            hot_params := concat_ws(',', hot_params, format('($3)[%s]', n));
        END LOOP;
        PERFORM id FROM splitjson._query(format('INSERT INTO %s (id,cold,%s%s) VALUES ($1,$2,%s%s) RETURNING id',meta.storage_name,hot_columns,extra_columns,hot_params,extra_values),
            ARRAY['bigint'::regtype,'splitjson.cold'::regtype,'jsonb[]'::regtype,meta.view_name::regtype],
            ARRAY[NEW.id::text,splitjson.pack(NEW.doc,meta.paths)::text,splitjson.slots(NEW.doc,meta.paths)::text,NEW::text],false) AS q(id bigint);
    ELSE
        IF NEW.doc IS NOT DISTINCT FROM OLD.doc THEN
            PERFORM id FROM splitjson._query(format('UPDATE %s SET id=$4%s WHERE id=$3 RETURNING id',meta.storage_name,extra_assignments),
                ARRAY['splitjson.cold'::regtype,'jsonb[]'::regtype,'bigint'::regtype,'bigint'::regtype,meta.view_name::regtype],
                ARRAY[NULL,NULL,OLD.id::text,NEW.id::text,NEW::text],false) AS q(id bigint);
        ELSE
            PERFORM id FROM splitjson._query(format('UPDATE %s SET id=$4,cold=$1,%s%s WHERE id=$3 RETURNING id',meta.storage_name,splitjson._assignments(meta.paths),extra_assignments),
                ARRAY['splitjson.cold'::regtype,'jsonb[]'::regtype,'bigint'::regtype,'bigint'::regtype,meta.view_name::regtype],
                ARRAY[splitjson.pack(NEW.doc,meta.paths)::text,splitjson.slots(NEW.doc,meta.paths)::text,OLD.id::text,NEW.id::text,NEW::text],false) AS q(id bigint);
        END IF;
    END IF;
    RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION splitjson._view_write() RETURNS trigger
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_view_entry';
REVOKE ALL ON FUNCTION splitjson._view_write() FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson._api_create_table(p_name text, p_paths jsonb, p_columns jsonb DEFAULT '{}') RETURNS regclass
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    parts text[];
    logical_name text;
    storage_name text;
    columns text := '';
    n integer;
    column_name text;
    declared_type jsonb;
    normalized_type text;
    normalized_columns jsonb := '{}';
    extra_select text := '';
BEGIN
    IF p_name IS NULL OR p_paths IS NULL OR p_columns IS NULL THEN
        RAISE EXCEPTION 'table name and paths must not be NULL' USING ERRCODE = '22023';
    END IF;
    PERFORM splitjson.validate_paths(p_paths);
    IF jsonb_array_length(p_paths) = 0 THEN
        RAISE EXCEPTION 'declare at least one hot path' USING ERRCODE = '22023';
    END IF;
    parts := parse_ident(p_name, true);
    IF cardinality(parts) <> 2 THEN
        RAISE EXCEPTION 'use a schema-qualified name, for example public.docs' USING ERRCODE = '22023';
    END IF;
    -- Avoid PostgreSQL identifier truncation creating ambiguous metadata names.
    IF octet_length(parts[1]) > 63 OR octet_length(parts[2]) > 63 THEN
        RAISE EXCEPTION 'schema and relation names must fit PostgreSQL identifiers' USING ERRCODE = '22023';
    END IF;
    logical_name := format('%I.%I', parts[1], parts[2]);
    IF jsonb_typeof(p_columns)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(p_columns))>64 THEN
        RAISE EXCEPTION 'business columns must be an object with at most 64 entries' USING ERRCODE='22023';
    END IF;
    n := 0;
    FOR column_name,declared_type IN SELECT key,value FROM jsonb_each(p_columns) ORDER BY key COLLATE "C" LOOP
        IF column_name IN ('id','doc') OR column_name='' OR octet_length(column_name)>63 OR jsonb_typeof(declared_type)<>'string' THEN
            RAISE EXCEPTION 'invalid business column name or type declaration' USING ERRCODE='22023';
        END IF;
        normalized_type := splitjson.column_type(declared_type #>> '{}');
        normalized_columns := normalized_columns || jsonb_build_object(column_name,normalized_type);
        n := n+1;
        columns := columns || format(',extra_%s %s',n,normalized_type);
        extra_select := extra_select || format(',extra_%s AS %I',n,column_name);
    END LOOP;
    storage_name := format('splitjson_storage.s_%s', nextval('splitjson._table_id_seq'));
    FOR n IN 1..jsonb_array_length(p_paths) LOOP
        columns := columns || format(',hot_%s jsonb', n);
    END LOOP;
    EXECUTE format('CREATE TABLE %s (id bigint PRIMARY KEY,cold splitjson.cold NOT NULL%s) WITH (fillfactor=70)',
                   storage_name, columns);
    EXECUTE format('ALTER TABLE %s ALTER COLUMN cold SET STORAGE EXTERNAL', storage_name);
    EXECUTE format('CREATE VIEW %s WITH (security_barrier=true) AS '
                   'SELECT id,splitjson.restore(cold,%s,%L::jsonb) AS doc%s FROM %s',
                   logical_name,splitjson._hot_array(p_paths),p_paths::text,extra_select,storage_name);
    PERFORM splitjson._secure_relation(storage_name::regclass);
    INSERT INTO splitjson._tables(view_name,storage_name,paths,business_columns,view_definition,storage_definition)
        VALUES(logical_name,storage_name,p_paths,normalized_columns,splitjson._view_definition(logical_name::regclass),
               splitjson._storage_definition(storage_name::regclass));
    EXECUTE format('CREATE TRIGGER pg_splitjson_write INSTEAD OF INSERT OR UPDATE OR DELETE ON %s '
                   'FOR EACH ROW EXECUTE FUNCTION splitjson._view_write()', logical_name);
    RETURN logical_name::regclass;
END $$;

CREATE OR REPLACE FUNCTION splitjson.create_table(p_name text, p_paths jsonb, p_columns jsonb DEFAULT '{}') RETURNS regclass
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

-- Fast path: the SELECT and UPDATE below mention only id and hot_N, never cold.
CREATE OR REPLACE FUNCTION splitjson._api_set_field(p_table regclass,p_id bigint,p_path text[],p_value jsonb,
                                      p_create_missing boolean DEFAULT true)
RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
BEGIN
    IF p_table IS NULL OR p_id IS NULL OR p_path IS NULL OR p_value IS NULL OR p_create_missing IS NULL THEN
        RAISE EXCEPTION 'arguments must not be NULL; use JSON null' USING ERRCODE='22023';
    END IF;
    PERFORM splitjson.assert_object_path('{}',p_path);
    p_path := ARRAY(SELECT unnest(p_path));
    RETURN splitjson._api_set_fields(p_table,p_id,jsonb_build_array(jsonb_build_object('path',to_jsonb(p_path),'value',p_value)),p_create_missing);
END $$;

CREATE OR REPLACE FUNCTION splitjson.set_field(p_table regclass,p_id bigint,p_path text[],p_value jsonb,
                                      p_create_missing boolean DEFAULT true)
RETURNS boolean
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_data_entry';

CREATE OR REPLACE FUNCTION splitjson._api_delete_field(p_table regclass,p_id bigint,p_path text[])
RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; hot jsonb[]; slot integer; relative text[]; doc jsonb; affected bigint;
BEGIN
    IF p_id IS NULL OR p_path IS NULL THEN RAISE EXCEPTION 'arguments must not be NULL' USING ERRCODE='22023'; END IF;
    PERFORM splitjson.assert_object_path('{}',p_path);
    p_path := ARRAY(SELECT unnest(p_path));
    meta := splitjson._lookup(p_table,'UPDATE');
    SELECT q.value INTO hot FROM splitjson._query(format('SELECT %s FROM %s WHERE id=$1 FOR UPDATE',splitjson._hot_array(meta.paths),meta.storage_name),
        ARRAY['bigint']::regtype[],ARRAY[p_id::text],false) AS q(value jsonb[]);
    GET DIAGNOSTICS affected=ROW_COUNT;
    IF affected=0 THEN RETURN false; END IF;
    slot := splitjson._hot_route(meta.paths,p_path,hot);
    IF slot IS NOT NULL AND jsonb_array_length(meta.paths->(slot-1))<cardinality(p_path)
       AND NOT splitjson._array_path_requires_fallback(
                    hot[slot],p_path[jsonb_array_length(meta.paths->(slot-1))+1:cardinality(p_path)]) THEN
        relative := p_path[jsonb_array_length(meta.paths->(slot-1))+1:cardinality(p_path)];
        PERFORM id FROM splitjson._query(format('UPDATE %s SET hot_%s=$1 WHERE id=$2 RETURNING id',meta.storage_name,slot),
            ARRAY['jsonb','bigint']::regtype[],ARRAY[(hot[slot] #- relative)::text,p_id::text],false) AS q(id bigint);
        RETURN true;
    END IF;
    SELECT q.value INTO doc FROM splitjson._query(format('SELECT splitjson.restore(cold,%s) FROM %s WHERE id=$1',splitjson._hot_array(meta.paths),meta.storage_name),
        ARRAY['bigint']::regtype[],ARRAY[p_id::text],false) AS q(value jsonb);
    RETURN splitjson._save(meta.storage_name,p_id,doc #- p_path,meta.paths);
END $$;

CREATE OR REPLACE FUNCTION splitjson.delete_field(p_table regclass,p_id bigint,p_path text[])
RETURNS boolean
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_data_entry';

CREATE OR REPLACE FUNCTION splitjson._api_drop_table(p_table regclass) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; owner_oid oid; caller_oid oid;
BEGIN
    IF p_table IS NULL THEN RAISE EXCEPTION 'table must not be NULL' USING ERRCODE = '22023'; END IF;
    SELECT * INTO meta FROM splitjson._tables WHERE view_name=splitjson._qualified_name(p_table);
    IF NOT FOUND THEN RAISE EXCEPTION 'relation is not a pg_splitjson managed view' USING ERRCODE = '22023'; END IF;
    SELECT relowner INTO owner_oid FROM pg_class WHERE oid = p_table;
    SELECT oid INTO caller_oid FROM pg_roles WHERE rolname = splitjson._caller();
    IF NOT pg_has_role(caller_oid, owner_oid, 'USAGE') THEN
        RAISE EXCEPTION 'must own the managed view to drop it' USING ERRCODE = '42501';
    END IF;
    PERFORM splitjson._validate_mapping(meta);
    PERFORM splitjson._assert_idle(p_table);
    -- Remove the registration in this transaction before protected DDL.
    -- Any dependency error rolls this deletion back with the DDL.
    DELETE FROM splitjson._tables WHERE view_name=meta.view_name;
    EXECUTE format('DROP VIEW %s', meta.view_name);
    EXECUTE format('DROP TABLE %s', meta.storage_name);
    EXECUTE format('DROP SEQUENCE IF EXISTS %s',meta.revision_sequence);
    DELETE FROM splitjson._tables WHERE view_name = meta.view_name;
END $$;

CREATE OR REPLACE FUNCTION splitjson.drop_table(p_table regclass) RETURNS void
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._api_set_fields(p_table regclass,p_id bigint,p_updates jsonb,
                                     p_create_missing boolean DEFAULT true)
RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE
    meta splitjson._tables%ROWTYPE;
    operation jsonb;
    path text[];
    relative text[];
    hot jsonb[];
    touched integer[] := '{}';
    slot integer;
    depth integer;
    all_hot boolean := true;
    affected bigint;
    assignments text;
    doc jsonb;
BEGIN
    IF p_id IS NULL OR p_updates IS NULL OR p_create_missing IS NULL OR jsonb_typeof(p_updates)<>'array' THEN
        RAISE EXCEPTION 'updates must be an array; arguments must not be NULL' USING ERRCODE='22023';
    END IF;
    IF jsonb_array_length(p_updates) NOT BETWEEN 1 AND 64 THEN
        RAISE EXCEPTION 'a batch must contain between 1 and 64 operations' USING ERRCODE='22023';
    END IF;
    FOR operation IN SELECT value FROM jsonb_array_elements(p_updates) LOOP
        IF jsonb_typeof(operation)<>'object' THEN
            RAISE EXCEPTION 'each operation must contain exactly path and value' USING ERRCODE='22023';
        END IF;
        IF (SELECT count(*) FROM jsonb_object_keys(operation))<>2 OR NOT operation ? 'path' OR NOT operation ? 'value' THEN
            RAISE EXCEPTION 'each operation must contain exactly path and value' USING ERRCODE='22023';
        END IF;
        IF jsonb_typeof(operation->'path')<>'array' OR
           EXISTS(SELECT 1 FROM jsonb_array_elements(operation->'path') e WHERE jsonb_typeof(e)<>'string') THEN
            RAISE EXCEPTION 'operation path must be an array of string segments' USING ERRCODE='22023';
        END IF;
        path := ARRAY(SELECT jsonb_array_elements_text(operation->'path'));
        PERFORM splitjson.assert_object_path('{}',path);
    END LOOP;
    meta := splitjson._lookup(p_table,'UPDATE');
    SELECT q.value INTO hot FROM splitjson._query(format('SELECT %s FROM %s WHERE id=$1 FOR UPDATE',splitjson._hot_array(meta.paths),meta.storage_name),
        ARRAY['bigint']::regtype[],ARRAY[p_id::text],false) AS q(value jsonb[]);
    GET DIAGNOSTICS affected=ROW_COUNT;
    IF affected=0 THEN RETURN false; END IF;
    FOR operation IN SELECT value FROM jsonb_array_elements(p_updates) LOOP
        path := ARRAY(SELECT jsonb_array_elements_text(operation->'path'));
        slot := splitjson._hot_route(meta.paths,path,hot);
        IF slot IS NULL THEN all_hot := false; EXIT; END IF;
        depth := jsonb_array_length(meta.paths->(slot-1));
        relative := path[depth+1:cardinality(path)];
        IF cardinality(relative)=0 THEN hot[slot] := operation->'value';
        ELSE hot[slot] := jsonb_set(hot[slot],relative,operation->'value',p_create_missing); END IF;
        touched := array_append(touched,slot);
    END LOOP;
    IF all_hot THEN
        SELECT string_agg(format('hot_%s=($1)[%s]',n,n),',' ORDER BY n) INTO assignments
            FROM (SELECT DISTINCT unnest(touched) AS n) t;
        PERFORM id FROM splitjson._query(format('UPDATE %s SET %s WHERE id=$2 RETURNING id',meta.storage_name,assignments),
            ARRAY['jsonb[]','bigint']::regtype[],ARRAY[hot::text,p_id::text],false) AS q(id bigint);
        RETURN true;
    END IF;
    SELECT q.value INTO doc FROM splitjson._query(format('SELECT splitjson.restore(cold,%s) FROM %s WHERE id=$1',splitjson._hot_array(meta.paths),meta.storage_name),
        ARRAY['bigint']::regtype[],ARRAY[p_id::text],false) AS q(value jsonb);
    FOR operation IN SELECT value FROM jsonb_array_elements(p_updates) LOOP
        path := ARRAY(SELECT jsonb_array_elements_text(operation->'path'));
        doc := jsonb_set(doc,path,operation->'value',p_create_missing);
    END LOOP;
    RETURN splitjson._save(meta.storage_name,p_id,doc,meta.paths);
END $$;

CREATE OR REPLACE FUNCTION splitjson.set_fields(p_table regclass,p_id bigint,p_updates jsonb,
                                     p_create_missing boolean DEFAULT true)
RETURNS boolean
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_data_entry';

CREATE OR REPLACE FUNCTION splitjson._api_increment_field(p_table regclass,p_id bigint,p_path text[],p_delta numeric DEFAULT 1)
RETURNS numeric
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; hot jsonb[]; slot integer; relative text[]; value jsonb; doc jsonb; result numeric; affected bigint;
BEGIN
    IF p_id IS NULL OR p_path IS NULL OR p_delta IS NULL OR p_delta::text IN ('NaN','Infinity','-Infinity') THEN
        RAISE EXCEPTION 'arguments must not be NULL and delta must be finite' USING ERRCODE='22023';
    END IF;
    PERFORM splitjson.assert_object_path('{}',p_path);
    p_path := ARRAY(SELECT unnest(p_path));
    meta := splitjson._lookup(p_table,'UPDATE');
    SELECT q.value INTO hot FROM splitjson._query(format('SELECT %s FROM %s WHERE id=$1 FOR UPDATE',splitjson._hot_array(meta.paths),meta.storage_name),
        ARRAY['bigint']::regtype[],ARRAY[p_id::text],false) AS q(value jsonb[]);
    GET DIAGNOSTICS affected=ROW_COUNT;
    IF affected=0 THEN RETURN NULL; END IF;
    slot := splitjson._hot_route(meta.paths,p_path,hot);
    IF slot IS NOT NULL THEN
        relative := p_path[jsonb_array_length(meta.paths->(slot-1))+1:cardinality(p_path)];
        value := hot[slot] #> relative;
    ELSE
        SELECT q.value INTO doc FROM splitjson._query(format('SELECT splitjson.restore(cold,%s) FROM %s WHERE id=$1',splitjson._hot_array(meta.paths),meta.storage_name),
            ARRAY['bigint']::regtype[],ARRAY[p_id::text],false) AS q(value jsonb);
        value := doc #> p_path;
    END IF;
    IF value IS NULL OR jsonb_typeof(value)<>'number' THEN
        RAISE EXCEPTION 'increment target must be an existing JSON number' USING ERRCODE='22023';
    END IF;
    result := value::text::numeric+p_delta;
    IF slot IS NOT NULL THEN
        IF cardinality(relative)=0 THEN value := to_jsonb(result);
        ELSE value := jsonb_set(hot[slot],relative,to_jsonb(result),false); END IF;
        PERFORM id FROM splitjson._query(format('UPDATE %s SET hot_%s=$1 WHERE id=$2 RETURNING id',meta.storage_name,slot),
            ARRAY['jsonb','bigint']::regtype[],ARRAY[value::text,p_id::text],false) AS q(id bigint);
    ELSE
        PERFORM splitjson._save(meta.storage_name,p_id,jsonb_set(doc,p_path,to_jsonb(result),false),meta.paths);
    END IF;
    RETURN result;
END $$;

CREATE OR REPLACE FUNCTION splitjson.increment_field(p_table regclass,p_id bigint,p_path text[],p_delta numeric DEFAULT 1)
RETURNS numeric
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_data_entry';

CREATE OR REPLACE FUNCTION splitjson._api_migrate_table(p_source regclass,p_target text,p_paths jsonb,
                                           p_doc_column name DEFAULT 'doc',p_id_column name DEFAULT 'id')
RETURNS regclass
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE
    columns jsonb;
    target regclass;
    names text := '';
    column_name text;
    declaration text;
BEGIN
    IF p_source IS NULL OR p_doc_column IS NULL OR p_id_column IS NULL OR p_doc_column=p_id_column OR
       NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=p_source AND relkind='r') THEN
        RAISE EXCEPTION 'source must be an ordinary table with distinct id/doc columns' USING ERRCODE='22023';
    END IF;
    -- Hold source DDL stable for the complete snapshot copy.
    EXECUTE format('LOCK TABLE %s IN ACCESS SHARE MODE',p_source);
    IF NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=p_source AND attname=p_id_column
                  AND NOT attisdropped AND atttypid='int8'::regtype) OR
       NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=p_source AND attname=p_doc_column
                  AND NOT attisdropped AND atttypid='jsonb'::regtype) THEN
        RAISE EXCEPTION 'source id must be bigint and document must be jsonb' USING ERRCODE='22023';
    END IF;
    SELECT coalesce(jsonb_object_agg(attname,format_type(atttypid,atttypmod)),'{}') INTO columns
        FROM pg_attribute WHERE attrelid=p_source AND attnum>0 AND NOT attisdropped
        AND attname NOT IN (p_id_column,p_doc_column);
    FOR column_name,declaration IN SELECT key,value FROM jsonb_each_text(columns) ORDER BY key COLLATE "C" LOOP
        names := names || format(',%I',column_name);
    END LOOP;
    target := splitjson.create_table(p_target,p_paths,columns);
    EXECUTE format('INSERT INTO %s (id,doc%s) SELECT %I,%I%s FROM %s',
                   target,names,p_id_column,p_doc_column,names,p_source);
    RETURN target;
END $$;

CREATE OR REPLACE FUNCTION splitjson.migrate_table(p_source regclass,p_target text,p_paths jsonb,
                                           p_doc_column name DEFAULT 'doc',p_id_column name DEFAULT 'id')
RETURNS regclass
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._api_get_field(p_table regclass,p_id bigint,p_path text[]) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; hot jsonb[]; slot integer; value jsonb; affected bigint;
BEGIN
    IF p_id IS NULL OR p_path IS NULL THEN RAISE EXCEPTION 'arguments must not be NULL' USING ERRCODE='22023'; END IF;
    PERFORM splitjson.assert_object_path('{}',p_path);
    p_path := ARRAY(SELECT unnest(p_path));
    meta := splitjson._lookup(p_table,'SELECT');
    SELECT q.value INTO hot FROM splitjson._query(format('SELECT %s FROM %s WHERE id=$1',splitjson._hot_array(meta.paths),meta.storage_name),
        ARRAY['bigint']::regtype[],ARRAY[p_id::text],true) AS q(value jsonb[]);
    GET DIAGNOSTICS affected=ROW_COUNT;
    IF affected=0 THEN RETURN NULL; END IF;
    slot := splitjson._hot_route(meta.paths,p_path,hot);
    IF slot IS NOT NULL THEN
        RETURN hot[slot] #> p_path[jsonb_array_length(meta.paths->(slot-1))+1:cardinality(p_path)];
    END IF;
    SELECT result INTO value FROM splitjson._query(format('SELECT splitjson.restore(cold,%s) #> $2 FROM %s WHERE id=$1',splitjson._hot_array(meta.paths),meta.storage_name),
        ARRAY['bigint','text[]']::regtype[],ARRAY[p_id::text,p_path::text],true) AS q(result jsonb);
    RETURN value;
END $$;

CREATE OR REPLACE FUNCTION splitjson.get_field(p_table regclass,p_id bigint,p_path text[]) RETURNS jsonb
LANGUAGE C STABLE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_data_entry';

CREATE OR REPLACE FUNCTION splitjson._find_query(p_meta splitjson._tables,p_path text[]) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog, pg_temp
AS $$
DECLARE candidates integer[]; condition text; missing text;
BEGIN
    candidates := splitjson._path_candidates(p_meta.paths,p_path);
    IF cardinality(candidates)>0 THEN
        SELECT string_agg(format('hot_%s=$1',n),' OR ') INTO condition FROM unnest(candidates) n;
        -- Native text paths may address shapes not covered by declared typed slots.
        IF EXISTS(SELECT 1 FROM unnest(p_path) key WHERE key ~ '^[[:space:]]*[+-]?[0-9]+$') THEN
            SELECT string_agg(format('hot_%s IS NULL',n),' AND ') INTO missing FROM unnest(candidates) n;
            condition := condition || format(' OR (%s AND splitjson.restore(cold,%s) #> $2=$1)',
                                               missing,splitjson._hot_array(p_meta.paths));
        END IF;
        RETURN format('SELECT id FROM %s WHERE %s',p_meta.storage_name,condition);
    END IF;
    RETURN format('SELECT id FROM %s WHERE splitjson.restore(cold,%s) #> $2=$1',p_meta.storage_name,splitjson._hot_array(p_meta.paths));
END $$;
REVOKE ALL ON FUNCTION splitjson._find_query(splitjson._tables,text[]) FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson._api_find_ids(p_table regclass,p_path text[],p_value jsonb) RETURNS SETOF bigint
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE;
BEGIN
    IF p_path IS NULL OR p_value IS NULL THEN RAISE EXCEPTION 'arguments must not be NULL' USING ERRCODE='22023'; END IF;
    meta := splitjson._lookup(p_table,'SELECT');
    RETURN QUERY SELECT id FROM splitjson._query(splitjson._find_query(meta,p_path),
        ARRAY['jsonb','text[]']::regtype[],ARRAY[p_value::text,p_path::text],true) AS q(id bigint);
END $$;

CREATE OR REPLACE FUNCTION splitjson.find_ids(p_table regclass,p_path text[],p_value jsonb) RETURNS SETOF bigint
LANGUAGE C STABLE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_data_entry';

-- Installer-only: the same SQL used by find_ids, planned by PostgreSQL.
CREATE OR REPLACE FUNCTION splitjson._api_explain_find_ids(p_table regclass,p_path text[],p_value jsonb) RETURNS SETOF text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE;
BEGIN
    IF p_path IS NULL OR p_value IS NULL THEN RAISE EXCEPTION 'arguments must not be NULL' USING ERRCODE='22023'; END IF;
    meta := splitjson._lookup(p_table,'SELECT');
    RETURN QUERY EXECUTE 'EXPLAIN (COSTS OFF) ' || splitjson._find_query(meta,p_path) USING p_value,p_path;
END $$;

CREATE OR REPLACE FUNCTION splitjson.explain_find_ids(p_table regclass,p_path text[],p_value jsonb) RETURNS SETOF text
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._create_index(p_table regclass,p_name text,p_slot integer,p_kind text) RETURNS regclass
LANGUAGE plpgsql SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; parts text[]; qualified_name text; expression text;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    IF p_name IS NULL OR p_slot IS NULL OR p_slot NOT BETWEEN 1 AND jsonb_array_length(meta.paths) OR
       p_kind IS NULL OR p_kind NOT IN ('jsonb','text') THEN
        RAISE EXCEPTION 'invalid index name, slot or kind (jsonb/text)' USING ERRCODE='22023';
    END IF;
    parts := parse_ident(p_name,true);
    IF cardinality(parts)<>1 OR octet_length(parts[1])>63 THEN
        RAISE EXCEPTION 'use a single PostgreSQL index identifier' USING ERRCODE='22023';
    END IF;
    SELECT format('%I.%I',n.nspname,parts[1]) INTO qualified_name
        FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid=meta.storage_name::regclass;
    expression := format('hot_%s',p_slot);
    IF p_kind='text' THEN expression := format('(%s #>> %L::text[])',expression,'{}'); END IF;
    EXECUTE format('CREATE INDEX %I ON %s USING btree (%s)',parts[1],meta.storage_name,expression);
    RETURN qualified_name::regclass;
END $$;
REVOKE ALL ON FUNCTION splitjson._create_index(regclass,text,integer,text) FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson._api_create_path_index(p_table regclass,p_name text,p_path text[],p_kind text) RETURNS regclass
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; candidates integer[];
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    IF p_path IS NULL THEN RAISE EXCEPTION 'path must not be NULL' USING ERRCODE='22023'; END IF;
    candidates := splitjson._path_candidates(meta.paths,p_path);
    IF cardinality(candidates)<>1 THEN
        RAISE EXCEPTION 'path must identify one registered slot; use a typed jsonb path for ambiguity' USING ERRCODE='22023';
    END IF;
    RETURN splitjson._create_index(p_table,p_name,candidates[1],p_kind);
END $$;

CREATE OR REPLACE FUNCTION splitjson.create_path_index(p_table regclass,p_name text,p_path text[],p_kind text) RETURNS regclass
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._api_create_path_index(p_table regclass,p_name text,p_path text[]) RETURNS regclass
LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
RETURN splitjson.create_path_index(p_table,p_name,p_path,'jsonb');

CREATE OR REPLACE FUNCTION splitjson.create_path_index(p_table regclass,p_name text,p_path text[]) RETURNS regclass
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._api_create_path_index(p_table regclass,p_name text,p_path jsonb,p_kind text DEFAULT 'jsonb') RETURNS regclass
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE meta splitjson._tables%ROWTYPE; slot integer;
BEGIN
    meta := splitjson._lookup(p_table,'SELECT');
    IF p_path IS NULL THEN RAISE EXCEPTION 'path must not be NULL' USING ERRCODE='22023'; END IF;
    PERFORM splitjson.validate_paths(jsonb_build_array(p_path));
    SELECT ord::integer INTO slot FROM jsonb_array_elements(meta.paths) WITH ORDINALITY p(path,ord) WHERE path=p_path;
    IF slot IS NULL THEN RAISE EXCEPTION 'path must be registered' USING ERRCODE='22023'; END IF;
    RETURN splitjson._create_index(p_table,p_name,slot,p_kind);
END $$;

CREATE OR REPLACE FUNCTION splitjson.create_path_index(p_table regclass,p_name text,p_path jsonb,p_kind text DEFAULT 'jsonb') RETURNS regclass
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._api_row_revision(p_table regclass,p_id bigint)
RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; revision bigint; affected bigint;
BEGIN
    IF p_id IS NULL THEN RAISE EXCEPTION 'id must not be NULL' USING ERRCODE='22023'; END IF;
    m := splitjson._lookup(p_table,'SELECT');
    SELECT q.value INTO revision FROM splitjson._query(format('SELECT row_revision FROM %s WHERE id=$1',m.storage_name),
        ARRAY['bigint']::regtype[],ARRAY[p_id::text],true) AS q(value bigint);
    GET DIAGNOSTICS affected=ROW_COUNT;
    IF affected=0 THEN RETURN NULL; END IF;
    RETURN splitjson._token(m.layout_epoch,p_id,revision);
END $$;

CREATE OR REPLACE FUNCTION splitjson.row_revision(p_table regclass,p_id bigint)
RETURNS text
LANGUAGE C STABLE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_data_entry';
REVOKE ALL ON FUNCTION splitjson.row_revision(regclass,bigint) FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson._api_set_fields_if_revision(p_table regclass,p_id bigint,p_token text,
                                                            p_updates jsonb,p_create_missing boolean DEFAULT true)
RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; revision bigint; affected bigint;
BEGIN
    IF p_id IS NULL OR p_token IS NULL OR p_updates IS NULL THEN
        RAISE EXCEPTION 'id, token and updates must not be NULL' USING ERRCODE='22023';
    END IF;
    m := splitjson._lookup(p_table,'UPDATE');
    SELECT q.value INTO revision FROM splitjson._query(format('SELECT row_revision FROM %s WHERE id=$1 FOR UPDATE',m.storage_name),
        ARRAY['bigint']::regtype[],ARRAY[p_id::text],false) AS q(value bigint);
    GET DIAGNOSTICS affected=ROW_COUNT;
    IF affected=0 THEN RETURN NULL; END IF;
    IF splitjson._token_revision(p_token,m.layout_epoch,p_id)<>revision THEN RAISE EXCEPTION 'stale revision token' USING ERRCODE='40001'; END IF;
    IF splitjson._api_set_fields(p_table,p_id,p_updates,p_create_missing) IS DISTINCT FROM true THEN RETURN NULL; END IF;
    SELECT q.value INTO revision FROM splitjson._query(format('SELECT row_revision FROM %s WHERE id=$1',m.storage_name),
        ARRAY['bigint']::regtype[],ARRAY[p_id::text],false) AS q(value bigint);
    RETURN splitjson._token(m.layout_epoch,p_id,revision);
END $$;

CREATE OR REPLACE FUNCTION splitjson.set_fields_if_revision(p_table regclass,p_id bigint,p_token text,
                                                            p_updates jsonb,p_create_missing boolean DEFAULT true)
RETURNS text
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_data_entry';
REVOKE ALL ON FUNCTION splitjson.set_fields_if_revision(regclass,bigint,text,jsonb,boolean) FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson._pointer(p_pointer text) RETURNS text[]
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog, pg_temp
AS $$
DECLARE raw text[]; result text[] := '{}'; token text; i integer;
BEGIN
    IF p_pointer='' THEN RETURN result; END IF;
    IF left(p_pointer,1)<>'/' THEN RAISE EXCEPTION 'JSON Pointer must start with /' USING ERRCODE='22023'; END IF;
    raw:=CASE WHEN p_pointer='/' THEN ARRAY[''] ELSE string_to_array(substr(p_pointer,2),'/') END;
    FOR i IN 1..cardinality(raw) LOOP
        token:=raw[i];
        IF token ~ '~([^01]|$)' THEN RAISE EXCEPTION 'invalid JSON Pointer escape' USING ERRCODE='22023'; END IF;
        result:=array_append(result,replace(replace(token,'~1','/'),'~0','~'));
    END LOOP;
    RETURN result;
END $$;

CREATE OR REPLACE FUNCTION splitjson._patch_get(p_doc jsonb,p_path text[]) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog, pg_temp
AS $$
DECLARE value jsonb:=p_doc; part text;
BEGIN
    FOREACH part IN ARRAY p_path LOOP
        IF jsonb_typeof(value)='array' THEN
            IF part !~ '^(0|[1-9][0-9]*)$' THEN RAISE EXCEPTION 'invalid JSON Pointer array index' USING ERRCODE='22023'; END IF;
            IF part::numeric>=jsonb_array_length(value) THEN RETURN NULL; END IF;
            value:=value->part::integer;
        ELSIF jsonb_typeof(value)='object' THEN value:=value->part;
        ELSE RETURN NULL; END IF;
        IF value IS NULL THEN RETURN NULL; END IF;
    END LOOP;
    RETURN value;
END $$;

CREATE OR REPLACE FUNCTION splitjson._patch_exists(p_doc jsonb,p_path text[]) RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog, pg_temp
RETURN splitjson._patch_get(p_doc,p_path) IS NOT NULL;

CREATE OR REPLACE FUNCTION splitjson._patch_add(p_doc jsonb,p_path text[],p_value jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog, pg_temp
AS $$
DECLARE parent text[]; key text; target jsonb; index integer; replacement jsonb;
BEGIN
    IF cardinality(p_path)=0 THEN RETURN p_value; END IF;
    parent:=p_path[1:cardinality(p_path)-1]; key:=p_path[cardinality(p_path)];
    target:=splitjson._patch_get(p_doc,parent);
    IF target IS NULL THEN RAISE EXCEPTION 'JSON Patch parent does not exist' USING ERRCODE='22023'; END IF;
    IF jsonb_typeof(target)='array' THEN
        IF key='-' THEN index:=jsonb_array_length(target);
        ELSIF key ~ '^(0|[1-9][0-9]*)$' THEN
            IF key::numeric>jsonb_array_length(target) THEN RAISE EXCEPTION 'JSON Patch array index is out of range' USING ERRCODE='22023'; END IF;
            index:=key::integer;
        ELSE RAISE EXCEPTION 'JSON Patch array index is invalid' USING ERRCODE='22023'; END IF;
        IF index<0 OR index>jsonb_array_length(target) THEN RAISE EXCEPTION 'JSON Patch array index is out of range' USING ERRCODE='22023'; END IF;
        replacement:=jsonb_insert(target,ARRAY[index::text],p_value,false);
    ELSIF jsonb_typeof(target)='object' THEN replacement:=jsonb_set(target,ARRAY[key],p_value,true);
    ELSE RAISE EXCEPTION 'JSON Patch parent is not a container' USING ERRCODE='22023'; END IF;
    IF cardinality(parent)=0 THEN RETURN replacement; END IF;
    RETURN jsonb_set(p_doc,parent,replacement,false);
END $$;

CREATE OR REPLACE FUNCTION splitjson._patch_remove(p_doc jsonb,p_path text[]) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog, pg_temp
AS $$
DECLARE parent text[]; key text; target jsonb; index integer; replacement jsonb;
BEGIN
    IF cardinality(p_path)=0 THEN RAISE EXCEPTION 'root remove is unsupported because doc is mandatory' USING ERRCODE='0A000'; END IF;
    IF NOT splitjson._patch_exists(p_doc,p_path) THEN RAISE EXCEPTION 'JSON Patch remove target does not exist' USING ERRCODE='22023'; END IF;
    parent:=p_path[1:cardinality(p_path)-1]; key:=p_path[cardinality(p_path)];
    target:=splitjson._patch_get(p_doc,parent);
    IF jsonb_typeof(target)='array' THEN
        IF key !~ '^(0|[1-9][0-9]*)$' THEN RAISE EXCEPTION 'JSON Patch array index is invalid' USING ERRCODE='22023'; END IF;
        index:=key::integer;
        IF index<0 OR index>=jsonb_array_length(target) THEN RAISE EXCEPTION 'JSON Patch array index is out of range' USING ERRCODE='22023'; END IF;
        replacement:=target-index;
    ELSIF jsonb_typeof(target)='object' THEN replacement:=target-key;
    ELSE RAISE EXCEPTION 'JSON Patch parent is not a container' USING ERRCODE='22023'; END IF;
    IF cardinality(parent)=0 THEN RETURN replacement; END IF;
    RETURN jsonb_set(p_doc,parent,replacement,false);
END $$;

CREATE OR REPLACE FUNCTION splitjson._apply_patch_doc(p_doc jsonb,p_patch jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog, pg_temp
AS $$
DECLARE operation jsonb; op text; path text[]; from_path text[]; source jsonb; result jsonb:=p_doc;
BEGIN
    IF jsonb_typeof(p_patch)<>'array' OR jsonb_array_length(p_patch)>64 THEN RAISE EXCEPTION 'JSON Patch must contain 0 to 64 operations' USING ERRCODE='22023'; END IF;
    FOR operation IN SELECT value FROM jsonb_array_elements(p_patch) LOOP
        IF jsonb_typeof(operation)<>'object' OR NOT operation ? 'op' OR NOT operation ? 'path' OR jsonb_typeof(operation->'path')<>'string' THEN
            RAISE EXCEPTION 'JSON Patch operation requires string op and path' USING ERRCODE='22023';
        END IF;
        op:=operation->>'op'; path:=splitjson._pointer(operation->>'path');
        IF op IN ('add','replace','test') AND NOT operation ? 'value' THEN RAISE EXCEPTION 'JSON Patch operation requires value' USING ERRCODE='22023'; END IF;
        IF op='add' THEN result:=splitjson._patch_add(result,path,operation->'value');
        ELSIF op='remove' THEN result:=splitjson._patch_remove(result,path);
        ELSIF op='replace' THEN
            IF NOT splitjson._patch_exists(result,path) THEN RAISE EXCEPTION 'JSON Patch replace target does not exist' USING ERRCODE='22023'; END IF;
            result:=CASE WHEN cardinality(path)=0 THEN operation->'value' ELSE jsonb_set(result,path,operation->'value',false) END;
        ELSIF op='test' THEN
            IF NOT splitjson._patch_exists(result,path) OR (CASE WHEN cardinality(path)=0 THEN result ELSE result #> path END) IS DISTINCT FROM operation->'value' THEN RAISE EXCEPTION 'JSON Patch test failed' USING ERRCODE='40001'; END IF;
        ELSIF op IN ('copy','move') THEN
            IF NOT operation ? 'from' OR jsonb_typeof(operation->'from')<>'string' THEN RAISE EXCEPTION 'JSON Patch copy/move requires from' USING ERRCODE='22023'; END IF;
            from_path:=splitjson._pointer(operation->>'from');
            IF NOT splitjson._patch_exists(result,from_path) THEN RAISE EXCEPTION 'JSON Patch source does not exist' USING ERRCODE='22023'; END IF;
            IF op='move' AND cardinality(path)>cardinality(from_path) AND (cardinality(from_path)=0 OR path[1:cardinality(from_path)]=from_path) THEN RAISE EXCEPTION 'JSON Patch cannot move into its own descendant' USING ERRCODE='22023'; END IF;
            source:=CASE WHEN cardinality(from_path)=0 THEN result ELSE result #> from_path END;
            IF op='move' AND from_path=path THEN CONTINUE; END IF;
            IF op='move' THEN result:=splitjson._patch_remove(result,from_path); END IF;
            result:=splitjson._patch_add(result,path,source);
        ELSE RAISE EXCEPTION 'unsupported JSON Patch operation: %',op USING ERRCODE='22023'; END IF;
    END LOOP;
    RETURN result;
END $$;

CREATE OR REPLACE FUNCTION splitjson._api_apply_patch(p_table regclass,p_id bigint,p_patch jsonb,p_expected_revision text DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; old_doc jsonb; new_doc jsonb; revision bigint; affected bigint;
    hot jsonb[]; operation jsonb; converted jsonb; op text; path text[]; from_path text[]; relative text[];
    slot integer; source_slot integer; depth integer; touched integer[]:='{}'; all_hot boolean:=true;
    assignments text; source_value jsonb; did_write boolean:=false;
BEGIN
    IF p_id IS NULL OR p_patch IS NULL OR jsonb_typeof(p_patch)<>'array' OR jsonb_array_length(p_patch)>64 THEN
        RAISE EXCEPTION 'JSON Patch must contain 0 to 64 operations' USING ERRCODE='22023'; END IF;
    -- Validate syntax even if the row is absent, without evaluating test.
    FOR operation IN SELECT value FROM jsonb_array_elements(p_patch) LOOP
        op:=operation->>'op';
        IF jsonb_typeof(operation)<>'object' OR jsonb_typeof(operation->'op')<>'string' OR
           jsonb_typeof(operation->'path')<>'string' OR op NOT IN ('add','remove','replace','move','copy','test') OR
           (op IN ('add','replace','test') AND NOT operation ? 'value') OR
           (op IN ('move','copy') AND jsonb_typeof(operation->'from') IS DISTINCT FROM 'string') THEN
            RAISE EXCEPTION 'invalid JSON Patch operation' USING ERRCODE='22023'; END IF;
        PERFORM splitjson._pointer(operation->>'path');
        IF op IN ('move','copy') THEN PERFORM splitjson._pointer(operation->>'from'); END IF;
        IF op='remove' AND operation->>'path'='' THEN RAISE EXCEPTION 'root remove requires an absent document' USING ERRCODE='0A000'; END IF;
    END LOOP;
    m:=splitjson._lookup(p_table,'UPDATE');
    SELECT q.hot_values,q.rev INTO hot,revision FROM splitjson._query(
        format('SELECT %s,row_revision FROM %s WHERE id=$1 FOR UPDATE',splitjson._hot_array(m.paths),m.storage_name),
        ARRAY['bigint']::regtype[],ARRAY[p_id::text],false) AS q(hot_values jsonb[],rev bigint);
    GET DIAGNOSTICS affected=ROW_COUNT; IF affected=0 THEN RETURN NULL; END IF;
    IF p_expected_revision IS NOT NULL AND splitjson._token_revision(p_expected_revision,m.layout_epoch,p_id)<>revision THEN
        RAISE EXCEPTION 'stale revision token' USING ERRCODE='40001'; END IF;
    FOR operation IN SELECT value FROM jsonb_array_elements(p_patch) LOOP
        op:=operation->>'op'; path:=splitjson._pointer(operation->>'path');
        IF cardinality(path)=0 THEN all_hot:=false; EXIT; END IF;
        slot:=splitjson._hot_route(m.paths,path,hot);
        IF slot IS NULL THEN all_hot:=false; EXIT; END IF;
        depth:=jsonb_array_length(m.paths->(slot-1)); relative:=path[depth+1:cardinality(path)];
        IF op='remove' AND cardinality(relative)=0 THEN all_hot:=false; EXIT; END IF;
        converted:=jsonb_set(operation,'{path}',to_jsonb(CASE WHEN cardinality(relative)=0 THEN '' ELSE
            '/'||array_to_string(ARRAY(SELECT replace(replace(k,'~','~0'),'/','~1') FROM unnest(relative) k),'/') END));
        IF op IN ('copy','move') THEN
            from_path:=splitjson._pointer(operation->>'from');
            IF op='move' AND cardinality(path)>cardinality(from_path) AND
               (cardinality(from_path)=0 OR path[1:cardinality(from_path)]=from_path) THEN
                RAISE EXCEPTION 'cannot move a value into its descendant' USING ERRCODE='22023'; END IF;
            source_slot:=splitjson._hot_route(m.paths,from_path,hot);
            IF source_slot IS NULL THEN all_hot:=false; EXIT; END IF;
            from_path:=from_path[jsonb_array_length(m.paths->(source_slot-1))+1:cardinality(from_path)];
            source_value:=splitjson._patch_get(hot[source_slot],from_path);
            IF source_value IS NULL THEN RAISE EXCEPTION 'JSON Patch source is absent' USING ERRCODE='22023'; END IF;
            IF op='move' THEN
                IF source_slot=slot AND from_path=relative THEN CONTINUE; END IF;
                IF cardinality(from_path)=0 THEN all_hot:=false; EXIT; END IF;
                hot[source_slot]:=splitjson._patch_remove(hot[source_slot],from_path);
                touched:=array_append(touched,source_slot);
            END IF;
            hot[slot]:=splitjson._patch_add(hot[slot],relative,source_value);
        ELSE
            hot[slot]:=splitjson._apply_patch_doc(hot[slot],jsonb_build_array(converted));
        END IF;
        IF op<>'test' THEN touched:=array_append(touched,slot); END IF;
    END LOOP;
    IF all_hot THEN
        IF cardinality(touched)=0 THEN RETURN splitjson._token(m.layout_epoch,p_id,revision); END IF;
        SELECT string_agg(format('hot_%s=($1)[%s]',n,n),',' ORDER BY n) INTO assignments
            FROM (SELECT DISTINCT unnest(touched) AS n) s;
        SELECT q.rev INTO revision FROM splitjson._query(format('UPDATE %s SET %s WHERE id=$2 RETURNING row_revision',m.storage_name,assignments),
            ARRAY['jsonb[]','bigint']::regtype[],ARRAY[hot::text,p_id::text],false) AS q(rev bigint);
    ELSE
        SELECT q.doc INTO old_doc FROM splitjson._query(format('SELECT splitjson.restore(cold,%s) FROM %s WHERE id=$1',splitjson._hot_array(m.paths),m.storage_name),
            ARRAY['bigint']::regtype[],ARRAY[p_id::text],false) AS q(doc jsonb);
        new_doc:=splitjson._apply_patch_doc(old_doc,p_patch);
        IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_patch) e WHERE e->>'op'<>'test') THEN
            PERFORM splitjson._save(m.storage_name,p_id,new_doc,m.paths);
            SELECT q.rev INTO revision FROM splitjson._query(format('SELECT row_revision FROM %s WHERE id=$1',m.storage_name),
                ARRAY['bigint']::regtype[],ARRAY[p_id::text],false) AS q(rev bigint);
        END IF;
    END IF;
    RETURN splitjson._token(m.layout_epoch,p_id,revision);
END $$;

CREATE OR REPLACE FUNCTION splitjson.apply_patch(p_table regclass,p_id bigint,p_patch jsonb,p_expected_revision text DEFAULT NULL)
RETURNS text
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_data_entry';
REVOKE ALL ON FUNCTION splitjson.apply_patch(regclass,bigint,jsonb,text) FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson._merge_patch(p_doc jsonb,p_patch jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog, pg_temp
AS $$
DECLARE result jsonb; key text; value jsonb; prior jsonb;
BEGIN
    IF jsonb_typeof(p_patch)<>'object' THEN RETURN p_patch; END IF;
    result:=CASE WHEN jsonb_typeof(p_doc)='object' THEN p_doc ELSE '{}'::jsonb END;
    FOR key,value IN SELECT e.key,e.value FROM jsonb_each(p_patch) AS e(key,value) LOOP
        IF value='null'::jsonb THEN result:=result-key;
        ELSE prior:=result->key; result:=jsonb_set(result,ARRAY[key],splitjson._merge_patch(prior,value),true); END IF;
    END LOOP;
    RETURN result;
END $$;

CREATE OR REPLACE FUNCTION splitjson._api_merge_patch(p_table regclass,p_id bigint,p_patch jsonb,p_expected_revision text DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; old_doc jsonb; new_doc jsonb; revision bigint; affected bigint;
BEGIN
    IF p_id IS NULL OR p_patch IS NULL THEN RAISE EXCEPTION 'id and patch must not be NULL' USING ERRCODE='22023'; END IF;
    m:=splitjson._lookup(p_table,'UPDATE');
    SELECT q.doc,q.rev INTO old_doc,revision FROM splitjson._query(format('SELECT splitjson.restore(cold,%s),row_revision FROM %s WHERE id=$1 FOR UPDATE',splitjson._hot_array(m.paths),m.storage_name),
        ARRAY['bigint']::regtype[],ARRAY[p_id::text],false) AS q(doc jsonb,rev bigint);
    GET DIAGNOSTICS affected=ROW_COUNT; IF affected=0 THEN RETURN NULL; END IF;
    IF p_expected_revision IS NOT NULL AND splitjson._token_revision(p_expected_revision,m.layout_epoch,p_id)<>revision THEN RAISE EXCEPTION 'stale or invalid revision token' USING ERRCODE='40001'; END IF;
    new_doc:=splitjson._merge_patch(old_doc,p_patch);
    IF new_doc IS NOT DISTINCT FROM old_doc THEN RETURN splitjson._token(m.layout_epoch,p_id,revision); END IF;
    PERFORM splitjson._save(m.storage_name,p_id,new_doc,m.paths);
    SELECT q.value INTO revision FROM splitjson._query(format('SELECT row_revision FROM %s WHERE id=$1',m.storage_name),
        ARRAY['bigint']::regtype[],ARRAY[p_id::text],false) AS q(value bigint);
    RETURN splitjson._token(m.layout_epoch,p_id,revision);
END $$;

CREATE OR REPLACE FUNCTION splitjson.merge_patch(p_table regclass,p_id bigint,p_patch jsonb,p_expected_revision text DEFAULT NULL)
RETURNS text
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_data_entry';
REVOKE ALL ON FUNCTION splitjson.merge_patch(regclass,bigint,jsonb,text) FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson._api_upsert_document(p_table regclass,p_id bigint,p_doc jsonb,p_business jsonb DEFAULT '{}')
RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; n integer; key text; cols text:='id,cold'; vals text:='$1,splitjson.pack($2,'; updates text:='cold=EXCLUDED.cold'; revision bigint; supplied boolean;
BEGIN
    IF p_id IS NULL OR p_doc IS NULL OR p_business IS NULL OR jsonb_typeof(p_business)<>'object' THEN RAISE EXCEPTION 'id, document and business object must be non-NULL' USING ERRCODE='22023'; END IF;
    m:=splitjson._lookup(p_table,'INSERT');
    PERFORM splitjson._lookup(p_table,'UPDATE');
    IF NOT has_column_privilege(splitjson._caller(),p_table,'id','INSERT') THEN RAISE EXCEPTION 'id INSERT permission required' USING ERRCODE='42501'; END IF;
    vals:=vals||quote_literal(m.paths::text)||'::jsonb)';
    FOR key IN SELECT jsonb_object_keys(p_business) LOOP IF NOT (m.business_columns ? key) THEN RAISE EXCEPTION 'unknown business column: %',key USING ERRCODE='22023'; END IF; END LOOP;
    FOR n IN 1..jsonb_array_length(m.paths) LOOP cols:=cols||format(',hot_%s',n); vals:=vals||format(',(splitjson.slots($2,%L::jsonb))[%s]',m.paths::text,n); updates:=updates||format(',hot_%s=EXCLUDED.hot_%s',n,n); END LOOP;
    n:=0;
    FOR key IN SELECT e.key FROM jsonb_each_text(m.business_columns) AS e(key,value) ORDER BY e.key COLLATE "C" LOOP
        n:=n+1; supplied:=p_business ? key;
        IF supplied AND (NOT has_column_privilege(splitjson._caller(),p_table,key,'INSERT') OR NOT has_column_privilege(splitjson._caller(),p_table,key,'UPDATE')) THEN
            RAISE EXCEPTION 'business INSERT/UPDATE permission required' USING ERRCODE='42501'; END IF;
        IF supplied THEN cols:=cols||format(',extra_%s',n); vals:=vals||format(',((jsonb_populate_record(NULL::%s,$3)).%I)',m.view_name,key); updates:=updates||format(',extra_%s=EXCLUDED.extra_%s',n,n); END IF;
    END LOOP;
    PERFORM splitjson._lookup(p_table,'UPDATE');
    SELECT q.rev INTO revision FROM splitjson._query(format('INSERT INTO %s(%s) VALUES(%s) ON CONFLICT(id) DO UPDATE SET %s RETURNING row_revision',m.storage_name,cols,vals,updates),
        ARRAY['bigint','jsonb','jsonb']::regtype[],ARRAY[p_id::text,p_doc::text,p_business::text],false) AS q(rev bigint);
    RETURN splitjson._token(m.layout_epoch,p_id,revision);
END $$;

CREATE OR REPLACE FUNCTION splitjson.upsert_document(p_table regclass,p_id bigint,p_doc jsonb,p_business jsonb DEFAULT '{}')
RETURNS text
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_data_entry';
REVOKE ALL ON FUNCTION splitjson.upsert_document(regclass,bigint,jsonb,jsonb) FROM PUBLIC;

CREATE OR REPLACE FUNCTION splitjson._api_find_ids_range(p_table regclass,p_path text[],p_kind text,p_lower jsonb DEFAULT NULL,p_upper jsonb DEFAULT NULL,
                                                    p_include_lower boolean DEFAULT true,p_include_upper boolean DEFAULT true,p_collation name DEFAULT NULL)
RETURNS SETOF bigint
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog, pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; candidates integer[]; slot integer; expr text; condition text:='true'; lower_value text; upper_value text; json_kind text;
BEGIN
    IF p_path IS NULL OR p_kind IS NULL OR p_include_lower IS NULL OR p_include_upper IS NULL THEN RAISE EXCEPTION 'range arguments must not be NULL' USING ERRCODE='22023'; END IF;
    m:=splitjson._lookup(p_table,'SELECT'); candidates:=splitjson._path_candidates(m.paths,p_path);
    IF cardinality(candidates)<>1 OR p_kind NOT IN ('numeric','boolean','text') THEN RAISE EXCEPTION 'range path and kind must identify one typed slot' USING ERRCODE='22023'; END IF;
    IF p_kind='numeric' THEN expr:='(hot_'||candidates[1]||' #>> ''{}'')::numeric'; json_kind:='number';
    ELSIF p_kind='boolean' THEN expr:='(hot_'||candidates[1]||' #>> ''{}'')::boolean'; json_kind:='boolean';
    ELSE expr:='(hot_'||candidates[1]||' #>> ''{}'')'; json_kind:='string'; END IF;
    IF p_lower IS NOT NULL THEN IF jsonb_typeof(p_lower)<>json_kind THEN RAISE EXCEPTION 'lower bound has wrong JSON type' USING ERRCODE='22023'; END IF; lower_value:=p_lower #>> '{}'; condition:=condition||format(' AND jsonb_typeof(hot_%s)=%L AND %s %s $1%s',candidates[1],json_kind,expr,CASE WHEN p_include_lower THEN '>=' ELSE '>' END,CASE WHEN p_kind='numeric' THEN '::numeric' WHEN p_kind='boolean' THEN '::boolean' ELSE '' END); END IF;
    IF p_upper IS NOT NULL THEN IF jsonb_typeof(p_upper)<>json_kind THEN RAISE EXCEPTION 'upper bound has wrong JSON type' USING ERRCODE='22023'; END IF; upper_value:=p_upper #>> '{}'; condition:=condition||format(' AND jsonb_typeof(hot_%s)=%L AND %s %s $2%s',candidates[1],json_kind,expr,CASE WHEN p_include_upper THEN '<=' ELSE '<' END,CASE WHEN p_kind='numeric' THEN '::numeric' WHEN p_kind='boolean' THEN '::boolean' ELSE '' END); END IF;
    RETURN QUERY SELECT id FROM splitjson._query(format('SELECT id FROM %s WHERE %s',m.storage_name,condition),
        ARRAY['text','text']::regtype[],ARRAY[lower_value,upper_value],true) AS q(id bigint);
END $$;

CREATE OR REPLACE FUNCTION splitjson.find_ids_range(p_table regclass,p_path text[],p_kind text,p_lower jsonb DEFAULT NULL,p_upper jsonb DEFAULT NULL,
                                                    p_include_lower boolean DEFAULT true,p_include_upper boolean DEFAULT true,p_collation name DEFAULT NULL)
RETURNS SETOF bigint
LANGUAGE C STABLE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_data_entry';
REVOKE ALL ON FUNCTION splitjson.find_ids_range(regclass,text[],text,jsonb,jsonb,boolean,boolean,name) FROM PUBLIC;


CREATE FUNCTION splitjson._api_enable_rls(p_table regclass,p_enabled boolean DEFAULT true,p_force boolean DEFAULT false)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE;
BEGIN
    IF p_enabled IS NULL OR p_force IS NULL THEN RAISE EXCEPTION 'RLS flags must not be NULL' USING ERRCODE='22023'; END IF;
    m:=splitjson._lookup(p_table,'SELECT'); PERFORM splitjson._assert_idle(p_table);
    EXECUTE format('ALTER TABLE %s %s ROW LEVEL SECURITY',m.storage_name,CASE WHEN p_enabled THEN 'ENABLE' ELSE 'DISABLE' END);
    EXECUTE format('ALTER TABLE %s %s FORCE ROW LEVEL SECURITY',m.storage_name,CASE WHEN p_force THEN '' ELSE 'NO' END);
    EXECUTE format('ALTER VIEW %s SET (security_invoker=%s)',m.view_name,CASE WHEN p_enabled THEN 'true' ELSE 'false' END);
    UPDATE splitjson._tables SET rls_enabled=p_enabled,rls_force=p_force,
        view_definition=splitjson._view_definition(p_table) WHERE view_name=m.view_name;
END $$;

CREATE OR REPLACE FUNCTION splitjson.enable_rls(p_table regclass,p_enabled boolean DEFAULT true,p_force boolean DEFAULT false)
RETURNS void
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE FUNCTION splitjson._api_set_policy(p_table regclass,p_name text,p_command text,p_roles name[],p_using text DEFAULT NULL,p_check text DEFAULT NULL,p_restrictive boolean DEFAULT false)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; role_sql text; r name; u text; c text;
BEGIN
    IF p_name IS NULL OR p_name='' OR octet_length(p_name)>63 OR p_command IS NULL OR p_command NOT IN ('select','insert','update','delete','all') OR
       p_roles IS NULL OR cardinality(p_roles)=0 OR p_restrictive IS NULL OR array_position(p_roles,NULL) IS NOT NULL OR
       (p_command='insert' AND p_using IS NOT NULL) OR (p_command IN ('select','delete') AND p_check IS NOT NULL) THEN
        RAISE EXCEPTION 'invalid policy declaration' USING ERRCODE='22023'; END IF;
    m:=splitjson._lookup(p_table,'SELECT'); PERFORM splitjson._assert_idle(p_table);
    FOREACH r IN ARRAY p_roles LOOP
        IF lower(r::text)<>'public' AND NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN
            RAISE EXCEPTION 'policy role does not exist' USING ERRCODE='42704'; END IF;
    END LOOP;
    u:=splitjson._policy_compile(p_table,m.storage_name::regclass,m.paths,p_using);
    c:=splitjson._policy_compile(p_table,m.storage_name::regclass,m.paths,p_check);
    SELECT string_agg(quote_ident(x.r),',') INTO role_sql FROM unnest(p_roles) x(r);
    EXECUTE format('DROP POLICY IF EXISTS %I ON %s',p_name,m.storage_name);
    EXECUTE format('CREATE POLICY %I ON %s AS %s FOR %s TO %s%s%s',p_name,m.storage_name,
        CASE WHEN p_restrictive THEN 'RESTRICTIVE' ELSE 'PERMISSIVE' END,upper(p_command),role_sql,
        CASE WHEN u IS NULL THEN '' ELSE ' USING ('||u||')' END,CASE WHEN c IS NULL THEN '' ELSE ' WITH CHECK ('||c||')' END);
    INSERT INTO splitjson._policies VALUES(m.view_name,p_name,p_command,p_roles,p_using,p_check,p_restrictive)
        ON CONFLICT(view_name,policy_name) DO UPDATE SET command=EXCLUDED.command,roles=EXCLUDED.roles,using_expression=EXCLUDED.using_expression,check_expression=EXCLUDED.check_expression,restrictive=EXCLUDED.restrictive;
    UPDATE splitjson._tables SET policy_definition=splitjson._policy_definition(m.storage_name::regclass) WHERE view_name=m.view_name;
END $$;

CREATE OR REPLACE FUNCTION splitjson.set_policy(p_table regclass,p_name text,p_command text,p_roles name[],p_using text DEFAULT NULL,p_check text DEFAULT NULL,p_restrictive boolean DEFAULT false)
RETURNS void
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE FUNCTION splitjson._api_drop_policy(p_table regclass,p_name text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE;
BEGIN
    m:=splitjson._lookup(p_table,'SELECT'); PERFORM splitjson._assert_idle(p_table);
    IF p_name IS NULL THEN RAISE EXCEPTION 'policy name must not be NULL' USING ERRCODE='22023'; END IF;
    EXECUTE format('DROP POLICY %I ON %s',p_name,m.storage_name);
    DELETE FROM splitjson._policies WHERE view_name=m.view_name AND policy_name=p_name;
    UPDATE splitjson._tables SET policy_definition=splitjson._policy_definition(m.storage_name::regclass) WHERE view_name=m.view_name;
END $$;

CREATE OR REPLACE FUNCTION splitjson.drop_policy(p_table regclass,p_name text) RETURNS void
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

-- Native partition routing, with id as the entire partition key.
CREATE FUNCTION splitjson._range_bound(p_bound jsonb) RETURNS text
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog,pg_temp
AS $$
DECLARE lo text; hi text;
BEGIN
    IF jsonb_typeof(p_bound)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(p_bound))<>2 OR
       NOT p_bound ? 'from' OR NOT p_bound ? 'to' THEN
        RAISE EXCEPTION 'range bounds require exactly from and to' USING ERRCODE='22023'; END IF;
    lo:=p_bound->>'from'; hi:=p_bound->>'to';
    IF (lo IS NOT NULL AND (jsonb_typeof(p_bound->'from')<>'number' OR lo !~ '^-?(0|[1-9][0-9]*)$')) OR
       (hi IS NOT NULL AND (jsonb_typeof(p_bound->'to')<>'number' OR hi !~ '^-?(0|[1-9][0-9]*)$')) THEN
        RAISE EXCEPTION 'range bounds must be bigint numbers or JSON null' USING ERRCODE='22023'; END IF;
    IF lo IS NOT NULL THEN lo:=lo::bigint::text; END IF;
    IF hi IS NOT NULL THEN hi:=hi::bigint::text; END IF;
    IF lo IS NOT NULL AND hi IS NOT NULL AND lo::bigint>=hi::bigint THEN
        RAISE EXCEPTION 'lower bound must precede upper bound' USING ERRCODE='22023'; END IF;
    RETURN format('FOR VALUES FROM (%s) TO (%s)',coalesce(lo,'MINVALUE'),coalesce(hi,'MAXVALUE'));
END $$;

CREATE FUNCTION splitjson._register_leaves(p_table regclass,p_storage regclass) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp
AS $$
BEGIN
    INSERT INTO splitjson._leaves(view_name,relation_name,bound,bound_spec)
        SELECT splitjson._qualified_name(p_table),splitjson._qualified_name(c.oid),pg_get_expr(c.relpartbound,c.oid),splitjson._partition_bound(c.oid)
        FROM pg_inherits i JOIN pg_class c ON c.oid=i.inhrelid WHERE i.inhparent=p_storage
        ON CONFLICT(relation_name) DO UPDATE SET bound=EXCLUDED.bound,bound_spec=EXCLUDED.bound_spec;
    UPDATE splitjson._tables SET partition_spec=(SELECT jsonb_agg(l.bound_spec ORDER BY (l.bound_spec->>'from')::bigint NULLS FIRST)
        FROM splitjson._leaves l WHERE l.view_name=splitjson._qualified_name(p_table)) WHERE view_name=splitjson._qualified_name(p_table) AND storage_mode='range';
END $$;

CREATE FUNCTION splitjson._assert_idle(p_table regclass) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp
AS $$
BEGIN
    IF EXISTS(SELECT 1 FROM splitjson._jobs WHERE (source_name=splitjson._qualified_name(p_table) OR target_name=splitjson._qualified_name(p_table))
              AND state NOT IN ('aborted','completed')) OR
       EXISTS(SELECT 1 FROM splitjson._replicas WHERE view_name=splitjson._qualified_name(p_table) AND state NOT IN ('detached','promoted')) THEN
        RAISE EXCEPTION 'managed relation has an active migration or replication dependency' USING ERRCODE='55000'; END IF;
END $$;

CREATE OR REPLACE FUNCTION splitjson._api_create_partitioned_table(p_name text,p_paths jsonb,p_columns jsonb,p_partition_spec jsonb) RETURNS regclass
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    parts text[];
    logical_name text;
    storage_name text;
    columns text := '';
    n integer;
    column_name text;
    declared_type jsonb;
    normalized_type text;
    normalized_columns jsonb := '{}';
    extra_select text := '';
    strategy text; modulus integer; bounds jsonb; lower_bound bigint; upper_bound bigint; leaf text;
BEGIN
    IF p_name IS NULL OR p_paths IS NULL OR p_columns IS NULL THEN
        RAISE EXCEPTION 'table name and paths must not be NULL' USING ERRCODE = '22023';
    END IF;
    IF p_partition_spec IS NULL THEN RAISE EXCEPTION 'partition spec must not be NULL' USING ERRCODE='22023'; END IF;
    IF jsonb_typeof(p_partition_spec)='object' THEN
        IF (SELECT count(*) FROM jsonb_object_keys(p_partition_spec))<>2 OR
           p_partition_spec->>'strategy'<>'hash' OR jsonb_typeof(p_partition_spec->'modulus')<>'number' OR
           (p_partition_spec->>'modulus') !~ '^[1-9][0-9]*$' THEN
            RAISE EXCEPTION 'hash specification requires only strategy=hash and integer modulus' USING ERRCODE='22023'; END IF;
        modulus:=(p_partition_spec->>'modulus')::integer;
        IF modulus NOT BETWEEN 1 AND 64 THEN RAISE EXCEPTION 'hash modulus must be 1..64' USING ERRCODE='22023'; END IF;
        strategy:='hash';
    ELSIF jsonb_typeof(p_partition_spec)='array' AND jsonb_array_length(p_partition_spec) BETWEEN 1 AND 64 THEN
        strategy:='range';
        FOR bounds IN SELECT value FROM jsonb_array_elements(p_partition_spec) LOOP
            PERFORM splitjson._range_bound(bounds);
        END LOOP;
    ELSE RAISE EXCEPTION 'partition specification must be hash or 1..64 range bounds' USING ERRCODE='22023'; END IF;
    PERFORM splitjson.validate_paths(p_paths);
    IF jsonb_array_length(p_paths) = 0 THEN
        RAISE EXCEPTION 'declare at least one hot path' USING ERRCODE = '22023';
    END IF;
    parts := parse_ident(p_name, true);
    IF cardinality(parts) <> 2 THEN
        RAISE EXCEPTION 'use a schema-qualified name, for example public.docs' USING ERRCODE = '22023';
    END IF;
    -- Avoid PostgreSQL identifier truncation creating ambiguous metadata names.
    IF octet_length(parts[1]) > 63 OR octet_length(parts[2]) > 63 THEN
        RAISE EXCEPTION 'schema and relation names must fit PostgreSQL identifiers' USING ERRCODE = '22023';
    END IF;
    logical_name := format('%I.%I', parts[1], parts[2]);
    IF jsonb_typeof(p_columns)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(p_columns))>64 THEN
        RAISE EXCEPTION 'business columns must be an object with at most 64 entries' USING ERRCODE='22023';
    END IF;
    n := 0;
    FOR column_name,declared_type IN SELECT key,value FROM jsonb_each(p_columns) ORDER BY key COLLATE "C" LOOP
        IF column_name IN ('id','doc') OR column_name='' OR octet_length(column_name)>63 OR jsonb_typeof(declared_type)<>'string' THEN
            RAISE EXCEPTION 'invalid business column name or type declaration' USING ERRCODE='22023';
        END IF;
        normalized_type := splitjson.column_type(declared_type #>> '{}');
        normalized_columns := normalized_columns || jsonb_build_object(column_name,normalized_type);
        n := n+1;
        columns := columns || format(',extra_%s %s',n,normalized_type);
        extra_select := extra_select || format(',extra_%s AS %I',n,column_name);
    END LOOP;
    storage_name := format('splitjson_storage.s_%s', nextval('splitjson._table_id_seq'));
    FOR n IN 1..jsonb_array_length(p_paths) LOOP
        columns := columns || format(',hot_%s jsonb', n);
    END LOOP;
    EXECUTE format('CREATE TABLE %s (id bigint PRIMARY KEY,cold splitjson.cold NOT NULL%s) PARTITION BY %s(id)',storage_name,columns,upper(strategy));
    EXECUTE format('ALTER TABLE %s ALTER COLUMN cold SET STORAGE EXTERNAL', storage_name);
    EXECUTE format('CREATE VIEW %s WITH (security_barrier=true) AS '
                   'SELECT id,splitjson.restore(cold,%s,%L::jsonb) AS doc%s FROM %s',
                   logical_name,splitjson._hot_array(p_paths),p_paths::text,extra_select,storage_name);
    IF strategy='hash' THEN
        FOR n IN 0..modulus-1 LOOP
            leaf:=storage_name||'_p'||n;
            EXECUTE format('CREATE TABLE %s PARTITION OF %s FOR VALUES WITH (MODULUS %s,REMAINDER %s) WITH (fillfactor=70)',leaf,storage_name,modulus,n);
            PERFORM splitjson._secure_relation(leaf::regclass);
        END LOOP;
    ELSE
        n:=0;
        FOR bounds IN SELECT value FROM jsonb_array_elements(p_partition_spec) LOOP
            leaf:=storage_name||'_p'||n; n:=n+1;
            EXECUTE format('CREATE TABLE %s PARTITION OF %s %s WITH (fillfactor=70)',leaf,storage_name,splitjson._range_bound(bounds));
            PERFORM splitjson._secure_relation(leaf::regclass);
        END LOOP;
    END IF;
    PERFORM splitjson._secure_relation(storage_name::regclass);
    INSERT INTO splitjson._tables(view_name,storage_name,paths,business_columns,view_definition,storage_definition,storage_mode,partition_spec)
        VALUES(logical_name,storage_name,p_paths,normalized_columns,splitjson._view_definition(logical_name::regclass),
               splitjson._storage_definition(storage_name::regclass),strategy,p_partition_spec);
    PERFORM splitjson._register_leaves(logical_name::regclass,storage_name::regclass);
    EXECUTE format('CREATE TRIGGER pg_splitjson_write INSTEAD OF INSERT OR UPDATE OR DELETE ON %s '
                   'FOR EACH ROW EXECUTE FUNCTION splitjson._view_write()', logical_name);
    RETURN logical_name::regclass;
END $$;

CREATE OR REPLACE FUNCTION splitjson.create_partitioned_table(p_name text,p_paths jsonb,p_columns jsonb,p_partition_spec jsonb) RETURNS regclass
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';


CREATE FUNCTION splitjson._api_create_partition(p_table regclass,p_name text,p_from bigint,p_to bigint)
RETURNS regclass
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; leaf text; parts text[];
BEGIN
    m:=splitjson._lookup(p_table,'SELECT'); PERFORM splitjson._assert_idle(p_table);
    parts:=parse_ident(p_name,true);
    IF m.storage_mode<>'range' OR p_name IS NULL OR cardinality(parts)<>1 OR octet_length(parts[1])>63 THEN
        RAISE EXCEPTION 'use a simple leaf name for RANGE(id) storage' USING ERRCODE='22023'; END IF;
    leaf:=format('splitjson_storage.%I',parts[1]);
    IF to_regclass(leaf) IS NOT NULL THEN RAISE EXCEPTION 'partition already exists' USING ERRCODE='42P07'; END IF;
    EXECUTE format('CREATE TABLE %s PARTITION OF %s %s WITH (fillfactor=70)',leaf,m.storage_name,
        splitjson._range_bound(jsonb_build_object('from',p_from,'to',p_to)));
    PERFORM splitjson._secure_relation(leaf::regclass);
    EXECUTE format('ALTER TABLE %s ALTER COLUMN cold SET STORAGE EXTERNAL',leaf);
    PERFORM splitjson._register_leaves(p_table,m.storage_name::regclass);
    RETURN leaf::regclass;
END $$;

CREATE OR REPLACE FUNCTION splitjson.create_partition(p_table regclass,p_name text,p_from bigint,p_to bigint)
RETURNS regclass
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE FUNCTION splitjson._api_attach_partition(p_table regclass,p_partition regclass,p_from bigint,p_to bigint)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; installer oid;
BEGIN
    m:=splitjson._lookup(p_table,'SELECT'); PERFORM splitjson._assert_idle(p_table);
    SELECT extowner INTO installer FROM pg_extension WHERE extname='pg_splitjson';
    IF m.storage_mode<>'range' OR p_partition IS NULL OR
       NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=p_partition AND relkind='r' AND relowner=installer AND relpersistence='p'
          AND relnamespace='splitjson_storage'::regnamespace AND NOT relrowsecurity AND NOT relforcerowsecurity) OR
       splitjson._storage_definition(p_partition) IS DISTINCT FROM m.storage_definition OR
       EXISTS(SELECT 1 FROM pg_inherits WHERE inhrelid=p_partition OR inhparent=p_partition) OR
       EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=p_partition) OR
       EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.oid=p_partition AND a.grantee<>installer) OR
       EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=p_partition AND NOT tgisinternal AND tgfoid<>'splitjson._revision_write()'::regprocedure) THEN
        RAISE EXCEPTION 'partition layout, ownership or security mismatch' USING ERRCODE='55000'; END IF;
    EXECUTE format('ALTER TABLE %s ATTACH PARTITION %s %s',m.storage_name,p_partition,
        splitjson._range_bound(jsonb_build_object('from',p_from,'to',p_to)));
    PERFORM splitjson._register_leaves(p_table,m.storage_name::regclass);
END $$;

CREATE OR REPLACE FUNCTION splitjson.attach_partition(p_table regclass,p_partition regclass,p_from bigint,p_to bigint)
RETURNS void
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE FUNCTION splitjson._api_detach_partition(p_table regclass,p_partition regclass)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE;
BEGIN
    m:=splitjson._lookup(p_table,'SELECT'); PERFORM splitjson._assert_idle(p_table);
    IF m.storage_mode<>'range' OR p_partition IS NULL OR NOT EXISTS(SELECT 1 FROM splitjson._leaves WHERE view_name=m.view_name AND relation_name=splitjson._qualified_name(p_partition)) THEN
        RAISE EXCEPTION 'partition is not a registered RANGE leaf' USING ERRCODE='22023'; END IF;
    EXECUTE format('ALTER TABLE %s DETACH PARTITION %s',m.storage_name,p_partition);
    DELETE FROM splitjson._leaves WHERE relation_name=splitjson._qualified_name(p_partition);
    UPDATE splitjson._tables SET partition_spec=coalesce((SELECT jsonb_agg(l.bound_spec ORDER BY (l.bound_spec->>'from')::bigint NULLS FIRST)
        FROM splitjson._leaves l WHERE l.view_name=m.view_name),'[]') WHERE view_name=m.view_name;
END $$;

CREATE OR REPLACE FUNCTION splitjson.detach_partition(p_table regclass,p_partition regclass)
RETURNS void
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE FUNCTION splitjson._collation(p_name name) RETURNS regcollation
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,pg_temp
AS $$
DECLARE names text[]; qualified text; result regcollation;
BEGIN
    IF p_name IS NULL THEN RETURN NULL; END IF;
    names:=CASE WHEN position('.' in p_name::text)=0 AND position('"' in p_name::text)=0 THEN ARRAY[p_name::text] ELSE parse_ident(p_name::text,true) END;
    IF cardinality(names)=1 THEN qualified:=quote_ident(names[1]);
    ELSIF cardinality(names)=2 THEN qualified:=format('%I.%I',names[1],names[2]);
    ELSE RAISE EXCEPTION 'invalid collation name' USING ERRCODE='22023'; END IF;
    result:=to_regcollation(qualified);
    IF result IS NULL THEN RAISE EXCEPTION 'collation does not exist' USING ERRCODE='42704'; END IF;
    RETURN result;
END $$;

CREATE FUNCTION splitjson._index_expression(p_slot integer,p_kind text,p_collation name) RETURNS text
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,pg_temp
AS $$
DECLARE result text; coll regcollation; qualified text;
BEGIN
    IF p_slot IS NULL OR p_kind IS NULL OR p_kind NOT IN ('jsonb','text','numeric','boolean') OR (p_kind<>'text' AND p_collation IS NOT NULL) THEN
        RAISE EXCEPTION 'invalid index kind or collation' USING ERRCODE='22023'; END IF;
    result:=format('hot_%s',p_slot);
    IF p_kind='text' THEN
        result:=format('(%s #>> %L::text[])',result,'{}'); coll:=splitjson._collation(p_collation);
        IF coll IS NOT NULL THEN SELECT format('%I.%I',n.nspname,c.collname) INTO qualified FROM pg_collation c JOIN pg_namespace n ON n.oid=c.collnamespace WHERE c.oid=coll;
            result:=format('(%s COLLATE %s)',result,qualified); END IF;
    ELSIF p_kind IN ('numeric','boolean') THEN
        result:=format('(CASE WHEN jsonb_typeof(hot_%s)=%L THEN (hot_%s #>> %L::text[])::%s END)',
            p_slot,CASE WHEN p_kind='numeric' THEN 'number' ELSE 'boolean' END,p_slot,'{}',p_kind);
    END IF;
    RETURN result;
END $$;

CREATE FUNCTION splitjson._api_declare_path_type(p_table regclass,p_path jsonb,p_kind text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; slot integer; guard text; typ text;
BEGIN
    m:=splitjson._lookup(p_table,'SELECT'); PERFORM splitjson._assert_idle(p_table);
    IF p_kind IS NULL OR p_kind NOT IN ('numeric','boolean') THEN RAISE EXCEPTION 'type must be numeric or boolean' USING ERRCODE='22023'; END IF;
    SELECT ord::integer INTO slot FROM jsonb_array_elements(m.paths) WITH ORDINALITY p(path,ord) WHERE path=p_path;
    IF slot IS NULL THEN RAISE EXCEPTION 'type declaration requires an exact registered hot path' USING ERRCODE='22023'; END IF;
    IF EXISTS(SELECT 1 FROM splitjson._slot_types WHERE view_name=m.view_name AND path=p_path AND kind<>p_kind) THEN
        RAISE EXCEPTION 'hot slot already has a different type' USING ERRCODE='22023'; END IF;
    guard:=format('pg_splitjson_type_%s_%s',slot,p_kind); typ:=CASE WHEN p_kind='numeric' THEN 'number' ELSE 'boolean' END;
    IF NOT EXISTS(SELECT 1 FROM splitjson._slot_types WHERE view_name=m.view_name AND path=p_path) THEN
        EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I CHECK (hot_%s IS NULL OR hot_%s=''null''::jsonb OR jsonb_typeof(hot_%s)=%L)',m.storage_name,guard,slot,slot,slot,typ);
        INSERT INTO splitjson._slot_types(view_name,path,kind,guard_name,definition)
            SELECT m.view_name,p_path,p_kind,guard,pg_get_constraintdef(oid,true) FROM pg_constraint WHERE conrelid=m.storage_name::regclass AND conname=guard;
    END IF;
END $$;

CREATE OR REPLACE FUNCTION splitjson.declare_path_type(p_table regclass,p_path jsonb,p_kind text) RETURNS void
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE FUNCTION splitjson._api_register_path_index(p_table regclass,p_index regclass,p_path jsonb,p_kind text,p_collation name DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; slot integer; expression text;
BEGIN
    m:=splitjson._lookup(p_table,'SELECT'); PERFORM splitjson._assert_idle(p_table);
    SELECT ord::integer INTO slot FROM jsonb_array_elements(m.paths) WITH ORDINALITY p(path,ord) WHERE path=p_path;
    IF slot IS NULL THEN RAISE EXCEPTION 'index must address an exact hot slot' USING ERRCODE='22023'; END IF;
    expression:=splitjson._index_expression(slot,p_kind,p_collation);
    IF p_kind IN ('numeric','boolean') AND NOT EXISTS(SELECT 1 FROM splitjson._slot_types WHERE view_name=m.view_name AND path=p_path AND kind=p_kind) THEN
        RAISE EXCEPTION 'declare matching path type before registering a typed index' USING ERRCODE='55000'; END IF;
    IF NOT splitjson._index_match(p_index,m.storage_name::regclass,expression) THEN
        RAISE EXCEPTION 'index expression, validity or layout does not match' USING ERRCODE='55000'; END IF;
    INSERT INTO splitjson._path_indexes(view_name,index_name,path,kind,collation_name,expression,definition)
        VALUES(m.view_name,splitjson._qualified_name(p_index),p_path,p_kind,splitjson._collation(p_collation)::text,expression,pg_get_indexdef(p_index))
        ON CONFLICT(index_name) DO UPDATE SET path=EXCLUDED.path,kind=EXCLUDED.kind,collation_name=EXCLUDED.collation_name,expression=EXCLUDED.expression,definition=EXCLUDED.definition;
END $$;

CREATE OR REPLACE FUNCTION splitjson.register_path_index(p_table regclass,p_index regclass,p_path jsonb,p_kind text,p_collation name DEFAULT NULL) RETURNS void
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE FUNCTION splitjson._api_create_path_index(p_table regclass,p_name text,p_path jsonb,p_kind text,p_collation name)
RETURNS regclass
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; slot integer; names text[]; expression text; idx regclass;
BEGIN
    m:=splitjson._lookup(p_table,'SELECT'); PERFORM splitjson._assert_idle(p_table); names:=parse_ident(p_name,true);
    IF p_name IS NULL OR cardinality(names)<>1 OR octet_length(names[1])>63 THEN RAISE EXCEPTION 'use a simple index name' USING ERRCODE='22023'; END IF;
    SELECT ord::integer INTO slot FROM jsonb_array_elements(m.paths) WITH ORDINALITY p(path,ord) WHERE path=p_path;
    IF slot IS NULL THEN RAISE EXCEPTION 'index requires an exact hot slot' USING ERRCODE='22023'; END IF;
    expression:=splitjson._index_expression(slot,p_kind,p_collation);
    IF p_kind IN ('numeric','boolean') THEN PERFORM splitjson._api_declare_path_type(p_table,p_path,p_kind); END IF;
    EXECUTE format('CREATE INDEX %I ON %s USING btree (%s)',names[1],m.storage_name,expression);
    idx:=format('splitjson_storage.%I',names[1])::regclass;
    PERFORM splitjson._api_register_path_index(p_table,idx,p_path,p_kind,p_collation);
    RETURN idx;
END $$;

CREATE OR REPLACE FUNCTION splitjson.create_path_index(p_table regclass,p_name text,p_path jsonb,p_kind text,p_collation name)
RETURNS regclass
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';
CREATE OR REPLACE FUNCTION splitjson._create_index(p_table regclass,p_name text,p_slot integer,p_kind text) RETURNS regclass
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE;
BEGIN
    m:=splitjson._lookup(p_table,'SELECT');
    RETURN splitjson._api_create_path_index(p_table,p_name,m.paths->(p_slot-1),p_kind,NULL);
END $$;

CREATE FUNCTION splitjson._api_create_path_index(p_table regclass,p_name text,p_path text[],p_kind text,p_collation name)
RETURNS regclass
LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
RETURN splitjson._api_create_path_index(p_table,p_name,to_jsonb(p_path),p_kind,p_collation);

CREATE OR REPLACE FUNCTION splitjson.create_path_index(p_table regclass,p_name text,p_path text[],p_kind text,p_collation name)
RETURNS regclass
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE FUNCTION splitjson._api_index_ddl(p_table regclass,p_name text,p_path jsonb,p_kind text,p_unique boolean,p_collation name)
RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; slot integer; names text[]; expression text;
BEGIN
    m:=splitjson._lookup(p_table,'SELECT'); names:=parse_ident(p_name,true);
    IF p_name IS NULL OR p_unique IS NULL OR cardinality(names)<>1 OR octet_length(names[1])>63 OR m.storage_mode<>'heap' THEN
        RAISE EXCEPTION 'use a simple index name and heap storage; partition_index_ddl handles partitioned storage' USING ERRCODE='22023'; END IF;
    SELECT ord::integer INTO slot FROM jsonb_array_elements(m.paths) WITH ORDINALITY p(path,ord) WHERE path=p_path;
    IF slot IS NULL THEN RAISE EXCEPTION 'index requires exact hot slot' USING ERRCODE='22023'; END IF;
    expression:=splitjson._index_expression(slot,p_kind,p_collation);
    IF p_kind IN ('numeric','boolean') AND NOT EXISTS(SELECT 1 FROM splitjson._slot_types WHERE view_name=m.view_name AND path=p_path AND kind=p_kind) THEN
        RAISE EXCEPTION 'run declare_path_type before generating typed concurrent DDL' USING ERRCODE='55000'; END IF;
    RETURN format('CREATE %sINDEX CONCURRENTLY %I ON %s USING btree (%s);',CASE WHEN p_unique THEN 'UNIQUE ' ELSE '' END,names[1],m.storage_name,expression);
END $$;

CREATE OR REPLACE FUNCTION splitjson.index_ddl(p_table regclass,p_name text,p_path jsonb,p_kind text,p_unique boolean,p_collation name)
RETURNS text
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';
CREATE OR REPLACE FUNCTION splitjson._api_index_ddl(p_table regclass,p_name text,p_path jsonb,p_kind text DEFAULT 'jsonb',p_unique boolean DEFAULT false)
RETURNS text
LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
RETURN splitjson._api_index_ddl(p_table,p_name,p_path,p_kind,p_unique,NULL);

CREATE OR REPLACE FUNCTION splitjson.index_ddl(p_table regclass,p_name text,p_path jsonb,p_kind text DEFAULT 'jsonb',p_unique boolean DEFAULT false)
RETURNS text
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE FUNCTION splitjson._api_partition_index_ddl(p_table regclass,p_name text,p_path jsonb,p_kind text DEFAULT 'jsonb',p_collation name DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; slot integer; names text[]; expr text; leaf text; idx text; parent text;
BEGIN
    m:=splitjson._lookup(p_table,'SELECT'); names:=parse_ident(p_name,true);
    IF p_name IS NULL OR cardinality(names)<>1 OR octet_length(names[1])>63 OR m.storage_mode='heap' THEN
        RAISE EXCEPTION 'use a simple index name and partitioned storage' USING ERRCODE='22023'; END IF;
    SELECT ord::integer INTO slot FROM jsonb_array_elements(m.paths) WITH ORDINALITY p(path,ord) WHERE path=p_path;
    IF slot IS NULL THEN RAISE EXCEPTION 'index requires an exact hot path' USING ERRCODE='22023'; END IF;
    expr:=splitjson._index_expression(slot,p_kind,p_collation); parent:=format('splitjson_storage.%I',names[1]);
    IF p_kind IN ('numeric','boolean') THEN RETURN NEXT format('SELECT splitjson.declare_path_type(%L::regclass,%L::jsonb,%L);',m.view_name,p_path,p_kind); END IF;
    RETURN NEXT format('CREATE INDEX %I ON ONLY %s USING btree (%s);',names[1],m.storage_name,expr);
    FOR leaf IN SELECT relation_name FROM splitjson._leaves WHERE view_name=m.view_name ORDER BY relation_name LOOP
        idx:=format('splitjson_storage.%I',left(names[1],38)||'_'||substr(md5(leaf),1,16));
        RETURN NEXT format('CREATE INDEX CONCURRENTLY %I ON %s USING btree (%s);',(parse_ident(idx,true))[2],leaf,expr);
        RETURN NEXT format('ALTER INDEX %s ATTACH PARTITION %s;',parent,idx);
    END LOOP;
    RETURN NEXT format('SELECT splitjson.register_path_index(%L::regclass,%L::regclass,%L::jsonb,%L,%L::name);',m.view_name,parent,p_path,p_kind,p_collation);
END $$;

CREATE OR REPLACE FUNCTION splitjson.partition_index_ddl(p_table regclass,p_name text,p_path jsonb,p_kind text DEFAULT 'jsonb',p_collation name DEFAULT NULL)
RETURNS SETOF text
LANGUAGE C VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_admin_entry';

CREATE OR REPLACE FUNCTION splitjson._api_find_ids_range(p_table regclass,p_path text[],p_kind text,p_lower jsonb DEFAULT NULL,p_upper jsonb DEFAULT NULL,
    p_include_lower boolean DEFAULT true,p_include_upper boolean DEFAULT false,p_collation name DEFAULT NULL)
RETURNS SETOF bigint
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE; slots integer[]; slot integer; expr text; conditions text; json_type text; dtype regtype;
BEGIN
    IF p_path IS NULL OR p_kind IS NULL OR p_include_lower IS NULL OR p_include_upper IS NULL OR p_kind NOT IN ('numeric','boolean','text') THEN
        RAISE EXCEPTION 'invalid typed range arguments' USING ERRCODE='22023'; END IF;
    PERFORM splitjson.assert_object_path('{}',p_path);
    m:=splitjson._lookup(p_table,'SELECT'); slots:=splitjson._path_candidates(m.paths,p_path);
    IF cardinality(slots)<>1 THEN RAISE EXCEPTION 'range requires a unique declared hot slot' USING ERRCODE='22023'; END IF;
    slot:=slots[1]; json_type:=CASE WHEN p_kind='numeric' THEN 'number' WHEN p_kind='text' THEN 'string' ELSE 'boolean' END;
    IF (p_lower IS NOT NULL AND jsonb_typeof(p_lower)<>json_type) OR (p_upper IS NOT NULL AND jsonb_typeof(p_upper)<>json_type) THEN
        RAISE EXCEPTION 'range bound has wrong JSON type' USING ERRCODE='22023'; END IF;
    IF p_lower IS NOT NULL AND p_upper IS NOT NULL AND p_kind<>'text' AND p_lower>p_upper THEN
        RAISE EXCEPTION 'lower bound exceeds upper bound' USING ERRCODE='22023'; END IF;
    IF p_kind IN ('numeric','boolean') AND NOT EXISTS(SELECT 1 FROM splitjson._slot_types WHERE view_name=m.view_name AND path=m.paths->(slot-1) AND kind=p_kind) THEN
        RAISE EXCEPTION 'declare a matching path type before using typed ranges' USING ERRCODE='55000'; END IF;
    expr:=splitjson._index_expression(slot,p_kind,p_collation); dtype:=p_kind::regtype;
    conditions:=expr||' IS NOT NULL';
    IF p_lower IS NOT NULL THEN conditions:=conditions||format(' AND %s %s $1',expr,CASE WHEN p_include_lower THEN '>=' ELSE '>' END); END IF;
    IF p_upper IS NOT NULL THEN conditions:=conditions||format(' AND %s %s $2',expr,CASE WHEN p_include_upper THEN '<=' ELSE '<' END); END IF;
    RETURN QUERY SELECT q.id FROM splitjson._query(format('SELECT id FROM %s WHERE %s',m.storage_name,conditions),
        ARRAY[dtype,dtype]::regtype[],ARRAY[p_lower #>> '{}',p_upper #>> '{}'],true) q(id bigint);
END $$;

CREATE OR REPLACE FUNCTION splitjson.find_ids_range(p_table regclass,p_path text[],p_kind text,p_lower jsonb DEFAULT NULL,p_upper jsonb DEFAULT NULL,
    p_include_lower boolean DEFAULT true,p_include_upper boolean DEFAULT false,p_collation name DEFAULT NULL)
RETURNS SETOF bigint
LANGUAGE C STABLE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_data_entry';

-- Logical portability: all data passes through the native caller executor.
CREATE FUNCTION splitjson._export_access(p_meta splitjson._tables,p_subset boolean) RETURNS void
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,pg_temp
AS $$
DECLARE key text; caller oid;
BEGIN
    IF p_subset IS NULL THEN RAISE EXCEPTION 'subset must not be NULL' USING ERRCODE='22023'; END IF;
    SELECT oid INTO caller FROM pg_roles WHERE rolname=splitjson._caller();
    FOR key IN SELECT jsonb_object_keys(p_meta.business_columns) LOOP
        IF NOT has_column_privilege(caller,p_meta.view_name,key,'SELECT') THEN
            RAISE EXCEPTION 'export requires SELECT on every business column' USING ERRCODE='42501'; END IF;
    END LOOP;
    IF NOT p_subset AND p_meta.rls_enabled AND NOT EXISTS(SELECT 1 FROM pg_roles WHERE oid=caller AND
        (rolsuper OR rolbypassrls OR (NOT p_meta.rls_force AND oid=(SELECT extowner FROM pg_extension WHERE extname='pg_splitjson')))) THEN
        RAISE EXCEPTION 'full export needs complete RLS authorization; choose subset explicitly' USING ERRCODE='42501'; END IF;
END $$;

CREATE FUNCTION splitjson._schema_plan(p_meta splitjson._tables,p_copy jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,pg_temp
AS $$
DECLARE plan jsonb:='[]'; item record; selected text; n integer; def_value jsonb; path jsonb;
BEGIN
    IF p_copy IS NULL OR jsonb_typeof(p_copy)<>'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_copy) x WHERE jsonb_typeof(x)<>'string' OR x #>> '{}' NOT IN ('not_null','defaults','checks','indexes','rls','acl','collation')) THEN
        RAISE EXCEPTION 'invalid schema copy selection' USING ERRCODE='22023'; END IF;
    FOR selected IN SELECT jsonb_array_elements_text(p_copy) LOOP
        IF selected='not_null' THEN
            FOR item IN SELECT attname,attnum FROM pg_attribute WHERE attrelid=p_meta.storage_name::regclass AND attname LIKE 'extra_%' AND attnotnull LOOP
                n:=substr(item.attname,7)::integer;
                SELECT key INTO selected FROM (SELECT key,row_number() OVER(ORDER BY key COLLATE "C") i FROM jsonb_each(p_meta.business_columns)) x WHERE i=n;
                plan:=plan||jsonb_build_array(jsonb_build_object('category','not_null','status','apply','column',selected));
            END LOOP;
        ELSIF selected='defaults' THEN
            FOR item IN SELECT d.oid,a.attname,pg_get_expr(d.adbin,d.adrelid) expression,d.adbin::text node FROM pg_attrdef d JOIN pg_attribute a ON a.attrelid=d.adrelid AND a.attnum=d.adnum WHERE d.adrelid=p_meta.storage_name::regclass AND a.attname LIKE 'extra_%' LOOP
                n:=substr(item.attname,7)::integer;
                SELECT key INTO selected FROM (SELECT key,row_number() OVER(ORDER BY key COLLATE "C") i FROM jsonb_each(p_meta.business_columns)) x WHERE i=n;
                -- Inspect native expression nodes; permit only builtin immutable
                -- constant expressions. User functions/domains are manual.
                IF splitjson._constant_default(item.oid) THEN
                    SELECT q.value INTO def_value FROM splitjson._query(format('SELECT to_jsonb(%s)',item.expression),ARRAY[]::regtype[],ARRAY[]::text[],true) q(value jsonb);
                    plan:=plan||jsonb_build_array(jsonb_build_object('category','defaults','status','apply','column',selected,'value',def_value));
                ELSE plan:=plan||jsonb_build_array(jsonb_build_object('category','defaults','status','manual','column',selected,'reason','nonconstant default; sequences and functions are not copied')); END IF;
            END LOOP;
        ELSIF selected='checks' THEN
            FOR item IN SELECT f.constraint_name,f.path,f.json_type,f.required FROM splitjson._field_checks f WHERE f.view_name=p_meta.view_name LOOP
                plan:=plan||jsonb_build_array(jsonb_build_object('category','checks','status','apply','name',item.constraint_name,'path',item.path,'type',item.json_type,'required',item.required));
            END LOOP;
            FOR item IN SELECT c.conname,c.contype FROM pg_constraint c WHERE c.conrelid=p_meta.storage_name::regclass AND contype IN ('c','f','u','x') AND
                c.conname NOT IN (SELECT f.constraint_name FROM splitjson._field_checks f WHERE f.view_name=p_meta.view_name UNION ALL SELECT t.guard_name FROM splitjson._slot_types t WHERE t.view_name=p_meta.view_name) LOOP
                plan:=plan||jsonb_build_array(jsonb_build_object('category','checks','status','manual','name',item.conname,'reason','unregistered CHECK, foreign key, unique or exclusion dependency')); END LOOP;
        ELSIF selected='indexes' THEN
            FOR item IN SELECT * FROM splitjson._path_indexes WHERE view_name=p_meta.view_name AND to_regclass(index_name) IS NOT NULL LOOP
                plan:=plan||jsonb_build_array(jsonb_build_object('category','indexes','status','apply','path',item.path,'kind',item.kind,'collation',item.collation_name)); END LOOP;
            FOR item IN SELECT indexrelid::regclass::text name FROM pg_index WHERE indrelid=p_meta.storage_name::regclass AND NOT indisprimary AND indexrelid NOT IN (SELECT to_regclass(index_name) FROM splitjson._path_indexes WHERE view_name=p_meta.view_name) LOOP
                plan:=plan||jsonb_build_array(jsonb_build_object('category','indexes','status','manual','name',item.name,'reason','unregistered index expression')); END LOOP;
        ELSIF selected='rls' THEN
            plan:=plan||jsonb_build_array(jsonb_build_object('category','rls','status','apply','enabled',p_meta.rls_enabled,'force',p_meta.rls_force,
                'policies',coalesce((SELECT jsonb_agg(to_jsonb(p)-'view_name') FROM splitjson._policies p WHERE view_name=p_meta.view_name),'[]')));
        ELSIF selected='acl' THEN
            FOR item IN SELECT a.grantee,bool_or(a.privilege_type IN ('INSERT','UPDATE','DELETE')) writable,
                array_agg(DISTINCT a.privilege_type ORDER BY a.privilege_type) privileges,bool_or(a.is_grantable) grantable
                FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a
                WHERE c.oid=p_meta.view_name::regclass AND a.grantee<>c.relowner GROUP BY a.grantee LOOP
                IF item.grantee=0 OR item.grantable OR item.privileges NOT IN (ARRAY['SELECT'],ARRAY['DELETE','INSERT','SELECT','UPDATE']) THEN
                    plan:=plan||jsonb_build_array(jsonb_build_object('category','acl','status','manual','reason','PUBLIC, partial/special privileges or grant options require an exact manual ACL deployment'));
                ELSE
                    plan:=plan||jsonb_build_array(jsonb_build_object('category','acl','status','apply','role',pg_get_userbyid(item.grantee),'mode',CASE WHEN item.writable THEN 'write' ELSE 'read' END));
                END IF;
            END LOOP;
            IF EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=p_meta.view_name::regclass AND attacl IS NOT NULL) THEN
                plan:=plan||jsonb_build_array(jsonb_build_object('category','acl','status','manual','reason','column ACL requires explicit review')); END IF;
        ELSIF selected='collation' THEN
            FOR item IN SELECT a.attname,a.attcollation::regcollation::text coll FROM pg_attribute a JOIN pg_type t ON t.oid=a.atttypid
                WHERE a.attrelid=p_meta.storage_name::regclass AND a.attname LIKE 'extra_%' AND a.attcollation<>t.typcollation LOOP
                n:=substr(item.attname,7)::integer;
                SELECT key INTO selected FROM (SELECT key,row_number() OVER(ORDER BY key COLLATE "C") i FROM jsonb_each(p_meta.business_columns)) x WHERE i=n;
                plan:=plan||jsonb_build_array(jsonb_build_object('category','collation','status','apply','column',selected,'collation',item.coll)); END LOOP;
        END IF;
    END LOOP;
    IF EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=p_meta.storage_name::regclass AND NOT tgisinternal AND tgfoid NOT IN ('splitjson._revision_write()'::regprocedure,'splitjson._storage_write_guard()'::regprocedure)) THEN
        plan:=plan||jsonb_build_array(jsonb_build_object('category','triggers','status','manual','reason','user triggers are never copied')); END IF;
    RETURN plan;
END $$;

CREATE FUNCTION splitjson._api_export_manifest(p_table regclass,p_subset boolean,p_copy jsonb DEFAULT '[]') RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp
AS $$
DECLARE m splitjson._tables%ROWTYPE;
BEGIN
    m:=splitjson._lookup(p_table,'SELECT'); PERFORM splitjson._export_access(m,p_subset);
    PERFORM q.id FROM splitjson._query(format('SELECT id FROM %s LIMIT 0',m.storage_name),ARRAY[]::regtype[],ARRAY[]::text[],true) q(id bigint);
    RETURN jsonb_build_object('format',2,'extension','pg_splitjson','version','0.3.0','view',m.view_name,'storage',m.storage_name,
        'epoch',m.layout_epoch,'generation',m.layout_generation,'mode',m.storage_mode,'partition_spec',m.partition_spec,
        'paths',m.paths,'business_columns',m.business_columns,'storage_definition',m.storage_definition,'subset',p_subset,
        'schema_plan',splitjson._schema_plan(m,p_copy),'credentials',NULL);
END $$;

CREATE OR REPLACE FUNCTION splitjson.export_manifest(p_table regclass,p_subset boolean,p_copy jsonb DEFAULT '[]') RETURNS jsonb
LANGUAGE C STABLE SECURITY INVOKER SET search_path=pg_catalog,pg_temp
AS 'MODULE_PATHNAME','pg_splitjson_data_entry';
